css:
.dbf-spend {
  /* re-theme with these four */
  --dbf-spend-bg: oklch(0.982 0.006 85);
  --dbf-spend-ink: oklch(0.24 0.02 55);
  --dbf-spend-accent: oklch(0.63 0.185 38);
  --dbf-spend-good: oklch(0.56 0.11 158);
  /* derived */
  --dbf-spend-card: color-mix(in oklch, var(--dbf-spend-bg) 30%, white);
  --dbf-spend-side: color-mix(in oklch, var(--dbf-spend-bg) 94%, var(--dbf-spend-ink));
  --dbf-spend-line: color-mix(in oklch, var(--dbf-spend-ink) 11%, transparent);
  --dbf-spend-soft: color-mix(in oklch, var(--dbf-spend-ink) 5%, transparent);
  --dbf-spend-mute: color-mix(in oklch, var(--dbf-spend-ink) 62%, var(--dbf-spend-bg));
  --dbf-spend-faint: color-mix(in oklch, var(--dbf-spend-ink) 40%, var(--dbf-spend-bg));
  --dbf-spend-tint: color-mix(in oklch, var(--dbf-spend-accent) 12%, var(--dbf-spend-card));
  --dbf-spend-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-spend-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-spend-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-spend-spring: linear(0, 0.013 0.6%, 0.05 1.2%, 0.2 2.5%, 0.46 4.4%, 0.81 7.2%, 1.01 9.8%, 1.08 12%, 1.1 13.5%, 1.08 15.6%, 1.02 19.5%, 0.99 23%, 0.985 27%, 1.002 38%, 1);
  width: 100%;
  height: var(--dbf-spend-h, 680px);
  container-type: inline-size; container-name: dbf-spend;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbf-spend-bg);
  color: var(--dbf-spend-ink);
  font: 13px/1.45 var(--dbf-spend-sans);
  accent-color: var(--dbf-spend-accent);
  box-shadow: inset 0 0 0 1px var(--dbf-spend-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ol, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(input) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--dbf-spend-accent); outline-offset: 2px; border-radius: 6px; }
  & .num { text-align: right; font-variant-numeric: tabular-nums; }
}
.dbf-spend__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-spend__shell { height: 100%; display: grid; grid-template-columns: 212px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dbf-spend__side {
  display: flex; flex-direction: column; gap: 4px; padding: 20px 14px 16px; min-height: 0; overflow: auto; scrollbar-width: thin;
  background: var(--dbf-spend-side); border-right: 1px solid var(--dbf-spend-line);
}
.dbf-spend__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 18px;
  & svg { width: 30px; height: 30px; flex: none; }
  & rect { fill: var(--dbf-spend-ink); }
  & path { fill: none; stroke: var(--dbf-spend-accent); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 750; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbf-spend-mute); letter-spacing: .02em; }
}
.dbf-spend__cap { margin: 2px 8px 6px; font-size: 10.5px; font-weight: 650; letter-spacing: .12em; text-transform: uppercase; color: var(--dbf-spend-faint); }
.dbf-spend__nav { display: grid; gap: 2px; }
.dbf-spend__item {
  position: relative; display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; text-align: left;
  color: var(--dbf-spend-mute); font-weight: 550; transition: background-color .2s, color .2s;
  &:hover { background: var(--dbf-spend-soft); color: var(--dbf-spend-ink); }
  &[aria-current="page"] { background: var(--dbf-spend-card); color: var(--dbf-spend-ink); font-weight: 650; box-shadow: 0 1px 0 var(--dbf-spend-line), 0 8px 18px -12px color-mix(in oklch, var(--dbf-spend-ink) 45%, transparent); }
  &[aria-current="page"] .dbf-spend__ic { color: var(--dbf-spend-accent); }
}
.dbf-spend__foot {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbf-spend-line); font-size: 12px; color: var(--dbf-spend-mute); text-wrap: pretty;
  & b { display: block; color: var(--dbf-spend-ink); font-weight: 650; }
}

/* ---------------------------------------------------------------- main + header */
.dbf-spend__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; padding: 16px 18px 16px; gap: 12px; }
.dbf-spend__head {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; grid-template-areas: "title seg" "chips chips"; gap: 10px 16px; align-items: end;
}
.dbf-spend__title {
  grid-area: title; min-width: 0;
  & h2 { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 780; letter-spacing: -.035em; line-height: 1.08; text-wrap: balance; }
}
.dbf-spend__eyebrow { font-size: 11.5px; font-weight: 600; letter-spacing: .04em; color: var(--dbf-spend-mute); font-variant-numeric: tabular-nums; margin-bottom: 3px; }
.dbf-spend__seg {
  grid-area: seg; display: inline-flex; padding: 3px; border-radius: 11px; background: var(--dbf-spend-soft); box-shadow: inset 0 0 0 1px var(--dbf-spend-line);
  & button { padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 650; color: var(--dbf-spend-mute); transition: background-color .2s, color .2s, box-shadow .2s; }
  & button:hover { color: var(--dbf-spend-ink); }
  & button[aria-checked="true"] { background: var(--dbf-spend-card); color: var(--dbf-spend-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbf-spend-ink) 20%, transparent); }
}
.dbf-spend__chips {
  grid-area: chips; display: flex; gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px;
  & button {
    flex: none; display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px 5px 9px; border-radius: 99px; font-size: 12px; font-weight: 600;
    color: var(--dbf-spend-mute); box-shadow: inset 0 0 0 1px var(--dbf-spend-line); transition: background-color .2s, color .2s, box-shadow .2s;
  }
  & button::before { content: ""; width: 14px; height: 14px; border-radius: 5px; box-shadow: inset 0 0 0 1.5px var(--dbf-spend-faint); transition: background-color .2s, box-shadow .2s; }
  & button:hover { color: var(--dbf-spend-ink); }
  & button[aria-pressed="true"] { color: var(--dbf-spend-ink); background: var(--dbf-spend-card); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbf-spend-ink) 22%, transparent); }
  & button[aria-pressed="true"]::before { background: var(--dbf-spend-ink); box-shadow: inset 0 0 0 1.5px var(--dbf-spend-ink), inset 0 0 0 3.5px var(--dbf-spend-card); }
  & .dbf-spend__all { font-weight: 700; }
  & small { font-weight: 500; color: var(--dbf-spend-faint); font-variant-numeric: tabular-nums; }
}

/* ---------------------------------------------------------------- views */
.dbf-spend__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  opacity: 1; translate: 0 0;
  transition: opacity .35s var(--dbf-spend-out), translate .5s var(--dbf-spend-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-spend__ov {
  grid-template-columns: minmax(0, 1.6fr) minmax(270px, 1fr);
  grid-template-rows: auto minmax(0, 1.05fr) minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "map daily" "map top";
}
.dbf-spend__panel {
  min-width: 0; min-height: 0; position: relative; display: flex; flex-direction: column;
  background: var(--dbf-spend-card); border-radius: 15px;
  box-shadow: inset 0 0 0 1px var(--dbf-spend-line), 0 18px 36px -32px color-mix(in oklch, var(--dbf-spend-ink) 70%, transparent);
  animation: dbf-spend-rise .7s var(--dbf-spend-out) both; animation-delay: calc(var(--i, 0) * 70ms + 80ms);
}
.dbf-spend__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px 8px; min-height: 42px;
  & h3 { font-size: 12.5px; font-weight: 700; letter-spacing: -.005em; }
}
.dbf-spend__hint { font-size: 11.5px; color: var(--dbf-spend-faint); text-wrap: pretty; text-align: right; }
.dbf-spend__link { font-size: 12px; font-weight: 650; color: var(--dbf-spend-accent); &:hover { text-decoration: underline; text-underline-offset: 3px; } }

/* ---------------------------------------------------------------- KPIs (subgrid so labels, values and deltas align) */
.dbf-spend__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); grid-template-rows: auto auto auto; gap: 0 10px;
  & > div {
    grid-row: span 3; display: grid; grid-template-rows: subgrid; row-gap: 1px; padding: 10px 14px 11px; border-radius: 13px;
    background: var(--dbf-spend-card); box-shadow: inset 0 0 0 1px var(--dbf-spend-line);
    animation: dbf-spend-rise .6s var(--dbf-spend-out) both; animation-delay: calc(var(--i, 0) * 55ms);
  }
  & dt { font-size: 11.5px; color: var(--dbf-spend-mute); font-weight: 600; }
  & dd { font-size: clamp(17px, 2.05cqi, 23px); font-weight: 760; letter-spacing: -.035em; line-height: 1.15; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd.small { font-size: clamp(14px, 1.5cqi, 16px); letter-spacing: -.02em; padding-top: 3px; }
  & span { font-size: 11.5px; color: var(--dbf-spend-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .up { color: color-mix(in oklch, var(--dbf-spend-accent) 85%, var(--dbf-spend-ink)); font-weight: 700; }
  & .dn { color: var(--dbf-spend-good); font-weight: 700; }
}

/* ---------------------------------------------------------------- treemap */
.dbf-spend__mapp { grid-area: map; --i: 1; }
.dbf-spend__crumb {
  display: flex; align-items: center; gap: 4px; min-width: 0; font-size: 12.5px; font-weight: 700;
  & button { padding: 3px 7px; margin: -3px -2px; border-radius: 7px; color: var(--dbf-spend-mute); }
  & button:hover { color: var(--dbf-spend-ink); background: var(--dbf-spend-soft); }
  & .sep { color: var(--dbf-spend-faint); font-weight: 400; }
  & .cur { display: inline-flex; align-items: center; gap: 6px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .cur i { width: 9px; height: 9px; border-radius: 3px; background: oklch(0.66 0.13 var(--h)); flex: none; }
}
.dbf-spend__tm { position: relative; flex: 1; min-height: 0; margin: 0 10px 10px; }
.dbf-spend__tile {
  position: absolute; container-type: size; text-align: left; border-radius: 9px;
  --fill: oklch(0.9 0.04 var(--h));
  --deep: oklch(0.4 0.08 var(--h));
  & .bg {
    position: absolute; inset: 0; border-radius: inherit; transform-origin: 0 0; background: var(--fill);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--deep) 14%, transparent);
    transition: background-color .25s, filter .25s;
  }
  & .lab {
    position: absolute; inset: 0; padding: clamp(6px, 6cqi, 12px); display: flex; flex-direction: column; gap: 1px; overflow: hidden;
    color: color-mix(in oklch, var(--deep) 75%, black);
  }
  & .lab b { font-size: clamp(11px, 7.2cqi, 15px); font-weight: 720; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }
  & .lab .amt { font-size: clamp(11.5px, 9cqi, 22px); font-weight: 760; letter-spacing: -.035em; font-variant-numeric: tabular-nums; margin-top: auto; line-height: 1.1; }
  & .lab .pct { font-size: 11px; font-weight: 600; font-variant-numeric: tabular-nums; opacity: .72; }
  &:hover .bg, &:focus-visible .bg { filter: brightness(.95) saturate(1.2); }
  &:focus-visible { outline-offset: -2px; outline-color: var(--dbf-spend-ink); }
  &.dim .bg { filter: saturate(.35) brightness(1.04); }
  &.gone { pointer-events: none; }
}
@container (height < 74px) { .dbf-spend__tile .lab .pct { display: none; } }
@container (height < 52px) { .dbf-spend__tile .lab .amt { display: none; } }
@container (width < 74px) { .dbf-spend__tile .lab .amt { font-size: 11px; } }
@container (width < 46px) or (height < 30px) { .dbf-spend__tile .lab { display: none; } }

/* ---------------------------------------------------------------- daily chart */
.dbf-spend__daily { grid-area: daily; --i: 2; }
.dbf-spend__dsum { font-size: 11.5px; color: var(--dbf-spend-mute); font-variant-numeric: tabular-nums; }
.dbf-spend__plot { position: relative; flex: 1; min-height: 0; margin: 0 6px 8px; border-radius: 8px; &:focus-visible { outline-offset: 0; } }
.dbf-spend__svg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; display: block;
  & .grid line { stroke: var(--dbf-spend-line); }
  & .grid text, & .xl text { fill: var(--dbf-spend-faint); font: 10.5px var(--dbf-spend-sans); font-variant-numeric: tabular-nums; }
  & .grid .zero { stroke: color-mix(in oklch, var(--dbf-spend-ink) 30%, transparent); }
  & .col rect { transition: opacity .2s; }
  & .col.we rect { opacity: .8; }
  & .xh { fill: color-mix(in oklch, var(--dbf-spend-ink) 7%, transparent); opacity: 0; transition: opacity .12s; }
  & .xh.on { opacity: 1; }
  &.focus .col rect:not(.f) { opacity: .2; }
  &.intro .col { transform-box: fill-box; transform-origin: 50% 100%; animation: dbf-spend-grow .7s var(--dbf-spend-out) both; animation-delay: calc(var(--i) * 6ms + 200ms); }
}

/* ---------------------------------------------------------------- top merchants */
.dbf-spend__top { grid-area: top; --i: 3; }
.dbf-spend__toplist {
  list-style: none; flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 0 8px 8px;
  & li { animation: dbf-spend-rise .5s var(--dbf-spend-out) both; animation-delay: calc(var(--i) * 40ms); }
  & button {
    width: 100%; display: grid; grid-template-columns: 8px minmax(0, 1fr) auto; grid-template-rows: auto 4px; gap: 3px 9px; align-items: center;
    padding: 7px 8px; border-radius: 9px; text-align: left; transition: background-color .15s;
  }
  & button:hover { background: var(--dbf-spend-soft); }
  & i { width: 8px; height: 8px; border-radius: 3px; background: oklch(0.66 0.13 var(--h)); }
  & .n { font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .v { font-weight: 700; font-variant-numeric: tabular-nums; }
  & .bar { grid-column: 2 / 4; height: 4px; border-radius: 2px; background: var(--dbf-spend-soft); overflow: hidden; }
  & .bar span { display: block; height: 100%; width: calc(var(--w) * 100%); border-radius: inherit; background: oklch(0.7 0.11 var(--h)); transform-origin: 0 50%; animation: dbf-spend-growx .8s var(--dbf-spend-out) both; animation-delay: calc(var(--i) * 40ms + 120ms); }
}

/* ---------------------------------------------------------------- merchants view */
.dbf-spend__mv { grid-template-columns: minmax(0, 1fr) 286px; grid-template-rows: minmax(0, 1fr); }
.dbf-spend__search {
  display: flex; align-items: center; gap: 7px; flex: 1; max-width: 300px; padding: 6px 10px; border-radius: 10px; background: var(--dbf-spend-soft);
  box-shadow: inset 0 0 0 1px var(--dbf-spend-line); color: var(--dbf-spend-mute); transition: box-shadow .2s;
  & input { flex: 1; min-width: 0; border: 0; background: none; outline: none; font-size: 12.5px; }
  &:has(input:focus-visible) { box-shadow: inset 0 0 0 2px var(--dbf-spend-accent); }
}
.dbf-spend__count { font-size: 11.5px; color: var(--dbf-spend-mute); white-space: nowrap; font-variant-numeric: tabular-nums; }
.dbf-spend__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbf-spend-ink) 20%, transparent) transparent; }
.dbf-spend__grid {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th {
    position: sticky; top: 0; z-index: 1; background: var(--dbf-spend-card); text-align: left; padding: 0 10px; height: 34px;
    font-size: 11px; font-weight: 650; letter-spacing: .05em; text-transform: uppercase; color: var(--dbf-spend-faint);
    border-bottom: 1px solid var(--dbf-spend-line); white-space: nowrap;
  }
  & th.num { text-align: right; }
  & th button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; border-radius: 5px; }
  & th button::after { content: ""; width: 7px; height: 7px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; rotate: 45deg; translate: 0 -2px; opacity: 0; transition: rotate .25s var(--dbf-spend-out), opacity .2s; }
  & th:hover button { color: var(--dbf-spend-ink); }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dbf-spend-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 225deg; translate: 0 2px; }
  & td { padding: 0 10px; height: 46px; border-bottom: 1px solid var(--dbf-spend-line); white-space: nowrap; }
  & tbody tr { cursor: pointer; background: var(--dbf-spend-card); transition: background-color .15s; }
  & tbody tr:hover { background: color-mix(in oklch, var(--dbf-spend-card), var(--dbf-spend-ink) 4%); }
  & tbody tr[aria-selected="true"] { background: var(--dbf-spend-tint); }
  & tbody tr[aria-selected="true"] td:first-child { box-shadow: inset 3px 0 0 var(--dbf-spend-accent); }
  & tbody tr:focus-visible { outline-offset: -2px; }
  & .mn { display: flex; align-items: center; gap: 9px; max-width: 260px; }
  & .mn > span { display: grid; min-width: 0; line-height: 1.25; }
  & .mn b { font-weight: 650; overflow: hidden; text-overflow: ellipsis; }
  & .mn small { font-size: 11.5px; color: var(--dbf-spend-mute); overflow: hidden; text-overflow: ellipsis; }
  & .mn i { width: 8px; height: 8px; border-radius: 3px; flex: none; background: oklch(0.66 0.11 var(--h)); }
  & .up { color: color-mix(in oklch, var(--dbf-spend-accent) 85%, var(--dbf-spend-ink)); font-weight: 650; }
  & .dn { color: var(--dbf-spend-good); font-weight: 650; }
  & .new { color: var(--dbf-spend-faint); }
  & svg { display: block; width: 84px; height: 22px; overflow: visible; margin-left: auto; }
  & svg path { fill: none; stroke: oklch(0.6 0.12 var(--h)); stroke-width: 1.5; stroke-linejoin: round; stroke-linecap: round; }
  & svg .a { fill: oklch(0.6 0.12 var(--h) / .12); stroke: none; }
}
@supports (animation-timeline: scroll()) {
  .dbf-spend__grid th { animation: dbf-spend-shade linear both; animation-timeline: scroll(nearest block); animation-range: 0 48px; }
}
.dbf-spend__det {
  overflow: auto; scrollbar-width: thin; padding: 16px;
  & .k { font-size: 11px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbf-spend-faint); }
  & h3 { font-size: 18px; font-weight: 760; letter-spacing: -.03em; line-height: 1.15; margin: 3px 0 2px; text-wrap: balance; }
  & .sub { color: var(--dbf-spend-mute); font-size: 12px; display: flex; align-items: center; gap: 6px; }
  & .sub i { width: 8px; height: 8px; border-radius: 3px; background: oklch(0.66 0.13 var(--h)); }
  & .big { font-size: 26px; font-weight: 780; letter-spacing: -.04em; font-variant-numeric: tabular-nums; margin-top: 14px; line-height: 1; }
  & .big + span { font-size: 12px; color: var(--dbf-spend-mute); }
  & .mo { display: grid; grid-template-columns: repeat(6, 1fr); align-items: end; gap: 6px; height: 96px; margin: 16px 0 4px; }
  & .mo div { display: flex; flex-direction: column; align-items: center; gap: 4px; height: 100%; justify-content: flex-end; font-size: 10.5px; color: var(--dbf-spend-faint); }
  & .mo span { width: 100%; border-radius: 4px 4px 2px 2px; background: oklch(0.72 0.08 var(--h) / .32); transform-origin: 50% 100%; animation: dbf-spend-grow .6s var(--dbf-spend-out) both; animation-delay: calc(var(--i) * 45ms); }
  & .mo .on span { background: oklch(0.66 0.13 var(--h)); }
  & .mo .on { color: var(--dbf-spend-ink); font-weight: 650; }
  & ul { list-style: none; padding: 0; margin: 12px 0 0; }
  & li { display: grid; grid-template-columns: 52px minmax(0, 1fr) auto; gap: 8px; padding: 7px 0; border-top: 1px solid var(--dbf-spend-line); font-size: 12px; font-variant-numeric: tabular-nums; }
  & li .d { color: var(--dbf-spend-mute); }
  & li .t { color: var(--dbf-spend-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & li b { font-weight: 650; }
  & .empty { color: var(--dbf-spend-mute); text-wrap: pretty; margin-top: 30px; text-align: center; }
}

/* ---------------------------------------------------------------- team matrix */
.dbf-spend__tv { grid-template-rows: auto minmax(0, 1fr); }
.dbf-spend__mx { --i: 1; }
