    const dy = b - tr.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: SOFT });
  });
  if (!flip) renderDetail();
}
$('.dbf-spend__grid thead').addEventListener('click', e => {
  const th = e.target.closest('th[data-k]'); if (!th) return;
  const k = th.dataset.k;
  S.sort = S.sort.k === k ? { k, dir: -S.sort.dir } : { k, dir: k === 'name' || k === 'cat' ? 1 : -1 };
  renderGrid(true);
});
$('.dbf-spend__search input').addEventListener('input', e => { S.q = e.target.value; renderGrid(false); });
tbody.addEventListener('click', e => { const tr = e.target.closest('tr'); if (!tr) return; S.sel = +tr.dataset.m; select(); });
tbody.addEventListener('keydown', e => {
  const tr = e.target.closest('tr'); if (!tr) return;
  let n = null;
  if (e.key === 'ArrowDown') n = tr.nextElementSibling; else if (e.key === 'ArrowUp') n = tr.previousElementSibling;
  else if (e.key === 'Home') n = tbody.firstElementChild; else if (e.key === 'End') n = tbody.lastElementChild;
  else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); S.sel = +tr.dataset.m; select(); return; }
  if (!n) return;
  e.preventDefault(); tr.tabIndex = -1; n.tabIndex = 0; n.focus();
});
function select() {
  $$('tr', tbody).forEach(tr => tr.setAttribute('aria-selected', String(+tr.dataset.m === S.sel)));
  renderDetail();
}
function renderDetail() {
  const det = $('.dbf-spend__det');
  if (S.sel == null) { det.innerHTML = '<p class="empty">Select a merchant to see its monthly run-rate and latest charges.</p>'; return; }
  const m = M[S.sel], c = CATS[m[1]], r = RANGES[S.range];
  const mo = [0, 0, 0, 0, 0, 0], txs = [];
  for (const t of TX) { if (t.m !== S.sel || !S.deps.has(t.dep)) continue; mo[dateOf(t.d).getMonth() - 3] += t.a; if (t.d >= r.a && t.d <= r.b) txs.push(t); }
  const mx = Math.max(1, ...mo), inR = k => { const a = new Date(2026, 3 + k, 1), b = new Date(2026, 4 + k, 0); return dateOf(r.a) <= b && dateOf(r.b) >= a; };
  const share = A.cat[m[1]] ? A.mer[S.sel] / A.cat[m[1]] : 0;
  det.innerHTML = `<p class="k">Merchant</p><h3>${esc(m[0])}</h3><p class="sub" style="--h:${c.h}"><i></i>${esc(c.n)}</p>
    <p class="big">${money(A.mer[S.sel])}</p><span>${r.label} · ${pct(share)} of ${esc(c.n.toLowerCase())}</span>
    <div class="mo" style="--h:${c.h}" aria-label="Monthly spend, April to September">${mo.map((v, k) => `<div class="${inR(k) ? 'on' : ''}" title="${MON[3 + k]}: ${money(v)}"><span style="height:${Math.max(2, v / mx * 72)}px;--i:${k}"></span>${MON[3 + k]}</div>`).join('')}</div>
    <ul>${txs.slice(-6).reverse().map(t => `<li><span class="d">${dlabel(t.d)}</span><span class="t">${esc(DEPTS[t.dep])}</span><b>${money2(t.a)}</b></li>`).join('') || '<li><span class="t">No charges in this period</span></li>'}</ul>`;
}

/* ------------------------------------------------------------------ team matrix */
const HEADS = [64, 38, 22, 18];
function renderMatrix() {
  const cols = CATS.map((c, i) => ({ i, n: c.n, s: c.s, h: c.h, v: A.mx.reduce((t, row) => t + row[i], 0) })).sort((a, b) => b.v - a.v);
  const mx = Math.max(1, ...A.mx.flat());
  let k = 0, grand = 0; const foot = Array(CATS.length).fill(0);
  const body = DEPTS.map((d, di) => {
    const on = S.deps.has(di), rowTot = A.mx[di].reduce((a, b) => a + b, 0);
    if (on) { A.mx[di].forEach((v, ci) => foot[ci] += v); grand += rowTot; }
    return `<tr class="${on ? '' : 'off'}"><th scope="row">${esc(d)}</th>${cols.map(c => { const v = A.mx[di][c.i]; return `<td>${v ? `<button type="button" data-d="${di}" data-c="${c.i}" style="--h:${c.h};--v:${(Math.sqrt(v / mx)).toFixed(3)};--i:${k++}" aria-label="${esc(d)}, ${esc(c.n)}: ${money(v)}">${compact(v)}<small>${pct(v / rowTot, 0)}</small></button>` : '<span class="z" aria-label="none">—</span>'}</td>`; }).join('')}<td class="tot">${money(rowTot)}</td></tr>`;
  }).join('');
  $('.dbf-spend__matrix').innerHTML = `<colgroup><col class="c0">${cols.map(() => '<col>').join('')}<col class="ct"></colgroup><thead><tr><th></th>${cols.map(c => `<th scope="col" style="--h:${c.h}" title="${esc(c.n)}">${esc(c.s)}<i></i></th>`).join('')}<th scope="col">Total</th></tr></thead><tbody>${body}</tbody>
    <tfoot><tr><th scope="row">${S.explicit ? 'Selected teams' : 'All teams'}</th>${cols.map(c => `<td class="tot">${compact(foot[c.i])}</td>`).join('')}<td class="tot">${money(grand)}</td></tr></tfoot>`;
  // team mix: 100% bars + spend per head
  const heads = DEPTS.reduce((a, d, i) => a + (S.deps.has(i) ? HEADS[i] : 0), 0);
  $('.dbf-spend__mixsum').textContent = `${heads} cardholders · ${money(heads ? grand / heads : 0)} per head`;
  $('.dbf-spend__mix').innerHTML = DEPTS.map((d, di) => {
    const row = A.mx[di], t = row.reduce((a, b) => a + b, 0);
    return `<li class="${S.deps.has(di) ? '' : 'off'}" style="--i:${di}"><div class="who"><b>${esc(d)}</b><span>${HEADS[di]} people · ${money(HEADS[di] ? t / HEADS[di] : 0)} each</span></div><div class="bar">${cols.map(c => row[c.i] ? `<button type="button" data-d="${di}" data-c="${c.i}" style="--w:${(row[c.i] / t * 100).toFixed(3)}%;background:${catFill(c.h)}" aria-label="${esc(d)}, ${esc(c.n)}: ${pct(row[c.i] / t)}"></button>` : '').join('')}</div><span class="t">${money(t)}</span></li>`;
  }).join('');
}
$('.dbf-spend__mix').addEventListener('pointermove', e => {
  const b = e.target.closest('button[data-c]'); if (!b) { hideTip(); return; }
  const di = +b.dataset.d, ci = +b.dataset.c, v = A.mx[di][ci], t = A.mx[di].reduce((a, x) => a + x, 0);
  showTip(`<b>${esc(DEPTS[di])}</b><span><small><i style="background:${catFill(CATS[ci].h)}"></i>${esc(CATS[ci].n)}</small><em>${money(v)}</em></span><span><small>Share of team</small><em>${pct(v / t)}</em></span>`, e.clientX, e.clientY);
});
$('.dbf-spend__mix').addEventListener('pointerleave', hideTip);
$('.dbf-spend__mix').addEventListener('click', e => {
  const b = e.target.closest('button[data-c]'); if (!b) return;
  S.deps = new Set([+b.dataset.d]); S.explicit = true; S.drill = +b.dataset.c; go('overview', true);
});
$('.dbf-spend__matrix').addEventListener('click', e => {
  const b = e.target.closest('button[data-d]'); if (!b) return;
  S.deps = new Set([+b.dataset.d]); S.explicit = true; S.drill = +b.dataset.c;
  go('overview', true);
});

/* ------------------------------------------------------------------ views */
const views = $$('.dbf-spend__view');
function go(v, recompute) {
  S.view = v; hideTip();
  $$('.dbf-spend__item').forEach(b => b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current'));
  views.forEach(el => { el.hidden = el.dataset.view !== v; });
  if (recompute) { compute(); syncHead(); renderKpis(); }
  if (v === 'overview') { renderMap(null, true); renderDaily(true); renderTop(); }
  if (v === 'merchants') { if (S.sel == null) { let b = 0; A.mer.forEach((x, i) => { if (x > A.mer[b]) b = i; }); S.sel = b; } renderGrid(false); const tr = rowEls.get(S.sel); if (tr && tr.isConnected) tr.scrollIntoView({ block: 'nearest' }); }
  if (v === 'teams') renderMatrix();
}
$('.dbf-spend__nav').addEventListener('click', e => { const b = e.target.closest('[data-view]'); if (b) go(b.dataset.view); });
$('.dbf-spend__nav').addEventListener('keydown', e => {
  const bs = $$('.dbf-spend__item'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  const j = ['ArrowDown', 'ArrowRight'].includes(e.key) ? (i + 1) % bs.length : ['ArrowUp', 'ArrowLeft'].includes(e.key) ? (i - 1 + bs.length) % bs.length : -1;
  if (j >= 0) { e.preventDefault(); bs[j].focus(); }
});

function update() {
  compute(); syncHead(); renderKpis();
  if (S.drill != null && !A.cat[S.drill]) S.drill = null;
  if (S.view === 'overview') { renderMap(); renderDaily(); renderTop(); }
  else if (S.view === 'merchants') renderGrid(false);
  else renderMatrix();
}

/* ------------------------------------------------------------------ mount */
compute(); syncHead(); renderKpis(); renderTop(); renderCrumb();
let lastW = 0, lastH = 0, lastPW = 0;
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  if (S.view !== 'overview') return;
  if (tm.clientWidth !== lastW || tm.clientHeight !== lastH) { const first = !lastW; lastW = tm.clientWidth; lastH = tm.clientHeight; renderMap(null, !first); }
  if (plot.clientWidth + plot.clientHeight * 7 !== lastPW) { const first = !lastPW; lastPW = plot.clientWidth + plot.clientHeight * 7; renderDaily(!first); }
});
ro.observe(tm); ro.observe(plot);

css:
.dbf-cashflow {
  /* re-theme with these four; everything else is derived */
  --dbf-cashflow-bg: oklch(0.2 0.02 165);
  --dbf-cashflow-ink: oklch(0.95 0.012 140);
  --dbf-cashflow-accent: oklch(0.89 0.185 128);
  --dbf-cashflow-out: oklch(0.72 0.135 32);
  --dbf-cashflow-in: oklch(from var(--dbf-cashflow-accent) calc(l - 0.17) calc(c * 0.42) calc(h + 52));
  --dbf-cashflow-warn: oklch(from var(--dbf-cashflow-out) calc(l + 0.1) c 78);
  --dbf-cashflow-card: color-mix(in oklch, var(--dbf-cashflow-bg), var(--dbf-cashflow-ink) 4.5%);
  --dbf-cashflow-raise: color-mix(in oklch, var(--dbf-cashflow-bg), var(--dbf-cashflow-ink) 9%);
  --dbf-cashflow-line: color-mix(in oklch, var(--dbf-cashflow-ink) 10%, transparent);
  --dbf-cashflow-soft: color-mix(in oklch, var(--dbf-cashflow-ink) 6%, transparent);
  --dbf-cashflow-mute: color-mix(in oklch, var(--dbf-cashflow-ink) 64%, var(--dbf-cashflow-bg));
  --dbf-cashflow-faint: color-mix(in oklch, var(--dbf-cashflow-ink) 42%, var(--dbf-cashflow-bg));
  --dbf-cashflow-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-cashflow-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-cashflow-out-e: cubic-bezier(.16, 1, .3, 1);
  width: 100%;
  height: var(--dbf-cashflow-h, 680px);
  container-type: inline-size; container-name: dbf-cashflow;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background:
    radial-gradient(120% 60% at 100% 0%, color-mix(in oklch, var(--dbf-cashflow-accent) 7%, transparent), transparent 60%),
    var(--dbf-cashflow-bg);
  color: var(--dbf-cashflow-ink);
  font: 13px/1.45 var(--dbf-cashflow-sans);
  accent-color: var(--dbf-cashflow-accent);
  color-scheme: dark;
  box-shadow: inset 0 0 0 1px var(--dbf-cashflow-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ul, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbf-cashflow-accent); outline-offset: 2px; border-radius: 6px; }
}
.dbf-cashflow__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-cashflow__shell { height: 100%; display: grid; grid-template-columns: 196px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dbf-cashflow__side {
  display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; overflow: auto; scrollbar-width: thin;
  border-right: 1px solid var(--dbf-cashflow-line); background: color-mix(in oklch, var(--dbf-cashflow-bg), black 18%);
}
.dbf-cashflow__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 22px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; flex: none; background: var(--dbf-cashflow-accent); fill: none; stroke: var(--dbf-cashflow-bg); stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 720; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbf-cashflow-mute); letter-spacing: .04em; }
}
.dbf-cashflow__nav { display: grid; gap: 2px; }
.dbf-cashflow__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; color: var(--dbf-cashflow-mute); font-weight: 550; text-align: left;
  transition: background-color .2s, color .2s;
  &:hover { background: var(--dbf-cashflow-soft); color: var(--dbf-cashflow-ink); }
  &[aria-current="page"] { background: var(--dbf-cashflow-raise); color: var(--dbf-cashflow-ink); font-weight: 650; }
  &[aria-current="page"] .dbf-cashflow__ic { color: var(--dbf-cashflow-accent); }
}
.dbf-cashflow__foot {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbf-cashflow-line); font-size: 11.5px; color: var(--dbf-cashflow-mute); line-height: 1.6;
  & b { display: block; color: var(--dbf-cashflow-ink); font-weight: 650; font-size: 12px; }
}

/* ---------------------------------------------------------------- main */
.dbf-cashflow__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 16px 18px; }
.dbf-cashflow__head { display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; }
.dbf-cashflow__title h2 { font-size: clamp(19px, 2.3cqi, 26px); font-weight: 720; letter-spacing: -.035em; line-height: 1.08; text-wrap: balance; }
.dbf-cashflow__eyebrow { font: 500 11px/1.4 var(--dbf-cashflow-mono); letter-spacing: .02em; color: var(--dbf-cashflow-mute); margin-bottom: 4px; }
.dbf-cashflow__seg {
  display: inline-flex; padding: 3px; border-radius: 11px; background: var(--dbf-cashflow-soft); box-shadow: inset 0 0 0 1px var(--dbf-cashflow-line);
  & button { padding: 6px 12px; border-radius: 8px; font-size: 12.5px; font-weight: 600; color: var(--dbf-cashflow-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dbf-cashflow-ink); }
  & button[aria-checked="true"] { background: var(--dbf-cashflow-accent); color: var(--dbf-cashflow-bg); }
  & button[data-s="down"][aria-checked="true"] { background: var(--dbf-cashflow-out); }
}
.dbf-cashflow__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  transition: opacity .35s var(--dbf-cashflow-out-e), translate .5s var(--dbf-cashflow-out-e);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-cashflow__fv {
  grid-template-columns: minmax(0, 1fr) 286px;
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "chart drv" "chart wk";
}
.dbf-cashflow__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; position: relative;
  background: var(--dbf-cashflow-card); border-radius: 15px; box-shadow: inset 0 0 0 1px var(--dbf-cashflow-line);
  animation: dbf-cashflow-rise .7s var(--dbf-cashflow-out-e) both; animation-delay: calc(var(--i, 0) * 70ms + 80ms);
}
.dbf-cashflow__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px 6px; min-height: 40px; flex-wrap: wrap;
  & h3 { font-size: 12.5px; font-weight: 650; letter-spacing: .005em; }
}
.dbf-cashflow__unit { font-size: 11px; font-weight: 500; color: var(--dbf-cashflow-faint); margin-left: 6px; }

/* ---------------------------------------------------------------- KPIs */
.dbf-cashflow__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0 10px; grid-template-rows: auto auto auto;
  & > div {
    grid-row: span 3; display: grid; grid-template-rows: subgrid; row-gap: 2px; padding: 10px 14px 11px; border-radius: 13px;
    background: var(--dbf-cashflow-card); box-shadow: inset 0 0 0 1px var(--dbf-cashflow-line);
    animation: dbf-cashflow-rise .6s var(--dbf-cashflow-out-e) both; animation-delay: calc(var(--i) * 55ms);
  }
  & dt { font-size: 11px; font-weight: 600; letter-spacing: .06em; text-transform: uppercase; color: var(--dbf-cashflow-faint); }
  & dd { font: 600 clamp(17px, 2cqi, 22px)/1.15 var(--dbf-cashflow-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & span { font-size: 11.5px; color: var(--dbf-cashflow-mute); font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .ok { color: var(--dbf-cashflow-accent); }
  & .bad { color: var(--dbf-cashflow-out); }
  & > div.alert { box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbf-cashflow-out) 45%, transparent); background: color-mix(in oklch, var(--dbf-cashflow-card), var(--dbf-cashflow-out) 8%); }
}

/* ---------------------------------------------------------------- chart */
.dbf-cashflow__chartp { grid-area: chart; --i: 1; }
.dbf-cashflow__legend {
  list-style: none; display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11px; color: var(--dbf-cashflow-mute);
  & li { display: inline-flex; align-items: center; gap: 6px; }
  & li::before { content: ""; width: 12px; height: 3px; border-radius: 2px; background: currentColor; }
  & .l-bal::before { background: var(--dbf-cashflow-accent); }
  & .l-band::before { height: 9px; background: color-mix(in oklch, var(--dbf-cashflow-accent) 22%, transparent); }
  & .l-cov::before { background: repeating-linear-gradient(90deg, var(--dbf-cashflow-warn) 0 4px, transparent 4px 7px); }
  & .l-in::before { width: 8px; height: 8px; background: var(--dbf-cashflow-in); }
  & .l-out::before { width: 8px; height: 8px; background: var(--dbf-cashflow-out); }
}
.dbf-cashflow__plot { position: relative; flex: 1; min-height: 0; margin: 0 8px 8px; border-radius: 10px; &:focus-visible { outline-offset: 0; } }
.dbf-cashflow__svg, .dbf-cashflow__svg2 {
  position: absolute; inset: 0; width: 100%; height: 100%; display: block; overflow: visible;
  & .gl { stroke: var(--dbf-cashflow-line); }
  & .gl.z { stroke: color-mix(in oklch, var(--dbf-cashflow-ink) 28%, transparent); }
  & text { fill: var(--dbf-cashflow-faint); font: 10.5px var(--dbf-cashflow-mono); font-variant-numeric: tabular-nums; }
  & .xm { fill: var(--dbf-cashflow-mute); font-weight: 600; }
  & .band { fill: color-mix(in oklch, var(--dbf-cashflow-accent) 13%, transparent); }
  & .bal { fill: none; stroke: var(--dbf-cashflow-accent); stroke-width: 2.25; stroke-linejoin: round; stroke-linecap: round; }
  & .glow { fill: none; stroke: var(--dbf-cashflow-accent); stroke-width: 8; opacity: .14; filter: blur(4px); stroke-linejoin: round; }
  & .cov { stroke: var(--dbf-cashflow-warn); stroke-width: 1.4; stroke-dasharray: 5 4; }
  & .covl { fill: var(--dbf-cashflow-warn); font-weight: 600; }
  & .breach { fill: color-mix(in oklch, var(--dbf-cashflow-out) 42%, transparent); }
  & .pt { fill: var(--dbf-cashflow-bg); stroke: var(--dbf-cashflow-accent); stroke-width: 1.75; transition: r .25s var(--dbf-cashflow-out-e); }
  & .pt.lo { stroke: var(--dbf-cashflow-out); }
  & .pt.sel { fill: var(--dbf-cashflow-accent); }
  & .rin { fill: var(--dbf-cashflow-in); }
  & .rout { fill: var(--dbf-cashflow-out); }
  & .net { stroke: var(--dbf-cashflow-ink); stroke-width: 2; stroke-linecap: round; }
  & .wkband { fill: color-mix(in oklch, var(--dbf-cashflow-ink) 5%, transparent); opacity: 0; transition: opacity .15s; }
  & .wkband.on { opacity: 1; }
  & .wkband.sel { opacity: 1; fill: color-mix(in oklch, var(--dbf-cashflow-accent) 8%, transparent); }
  & .div { stroke: var(--dbf-cashflow-line); stroke-dasharray: 2 3; }
  & .ptag { fill: var(--dbf-cashflow-faint); font-size: 10px; letter-spacing: .06em; }
  &.intro .bal, &.intro .glow { stroke-dasharray: 1; stroke-dashoffset: 1; animation: dbf-cashflow-draw 1.5s var(--dbf-cashflow-out-e) .25s forwards; }
  &.intro .band, &.intro .breach { animation: dbf-cashflow-fade .9s ease-out .9s both; }
  &.intro .pt { animation: dbf-cashflow-fade .4s ease-out both; animation-delay: calc(var(--i) * 90ms + 400ms); }
  &.intro .bar { transform-box: fill-box; animation: dbf-cashflow-grow .7s var(--dbf-cashflow-out-e) both; animation-delay: calc(var(--i) * 45ms + 150ms); }
  &.intro .rin { transform-origin: 50% 100%; }
  &.intro .rout { transform-origin: 50% 0; }
  & .sline { fill: none; stroke-width: 2; stroke-linejoin: round; }
  & .sline.base { stroke: var(--dbf-cashflow-accent); }
  & .sline.down { stroke: var(--dbf-cashflow-out); }
  & .sline.up { stroke: var(--dbf-cashflow-in); }
  & .sline.dim { opacity: .5; stroke-width: 1.4; stroke-dasharray: 3 3; }
