const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const NS = 'http://www.w3.org/2000/svg';
const UID = 'dbf-cashflow-' + Math.random().toString(36).slice(2, 8);
const spring = t => t >= 1 ? 1 : 1 - Math.exp(-6.5 * t) * Math.cos(8.5 * t);
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const wkDate = (w, d = 0) => new Date(2026, 9, 5 + 7 * w + d);
const dl = dt => MON[dt.getMonth()] + ' ' + dt.getDate();
const NF = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const fmtM = k => { const a = Math.abs(k), s = k < 0 ? '−' : ''; return a >= 1000 ? `${s}$${(a / 1000).toFixed(2)}M` : `${s}$${Math.round(a)}k`; };
const fmtS = k => (k > 0 ? '+' : k < 0 ? '−' : '') + fmtM(Math.abs(k)).replace('−', '');
const fmtL = k => k === 0 ? '–' : k < 0 ? `(${NF.format(-k)})` : NF.format(k);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

/* ------------------------------------------------------------------ the model ($ thousands) */
const HIST = [968, 1012, 990, 1046, 1031, 1078, 1052, 1094];            // invoiced sales, 8 weeks to Oct 2
const PLAN = [1088, 1104, 1121, 1139, 1172, 1210, 1268, 1362, 1240, 1295, 1338, 1402, 905]; // plan, Oct 5 - Dec 28
const LAG = [[3, .12], [4, .30], [5, .33], [6, .15], [8, .07]];       // weeks from invoice to cash; 3% collects beyond horizon
const SCEN = { down: { n: 'Downside', f: .86, slip: 10, d: 'Sales −14%, customers pay 10 days late' }, base: { n: 'Base', f: 1, slip: 0, d: 'Plan sales, current payment behaviour' }, up: { n: 'Upside', f: 1.06, slip: -3, d: 'Sales +6%, collections 3 days faster' } };
const OPEN = 3180, COV = 1500;
const LINES = [
  ['coll', 'Customer collections', 1], ['oth', 'Vendor rebates & other', 1], ['fin', 'Revolver draw', 1],
  ['sup', 'Inventory & suppliers', -1], ['pay', 'Payroll & benefits', -1], ['frt', 'Freight & fuel', -1], ['rent', 'Rent & facilities', -1],
  ['opx', 'Operating expenses', -1], ['tax', 'Sales & income tax', -1], ['debt', 'Debt service', -1], ['cap', 'Capital expenditure', -1]
];
function model(sc, D) {
  const S = SCEN[sc], slip = S.slip + D.slip;
  const sales = w => w < 0 ? HIST[Math.max(0, HIST.length + w)] : PLAN[w] * S.f;
  const plan = w => w < 0 ? HIST[Math.max(0, HIST.length + w)] : PLAN[w];
  const L = {}; LINES.forEach(([k]) => L[k] = Array(13).fill(0));
  for (let w = 0; w < 13; w++) {
    for (const [l, p] of LAG) { const x = l + slip / 7, a = Math.floor(x), f = x - a; L.coll[w] += p * ((1 - f) * sales(w - a) + f * sales(w - a - 1)); }
    L.sup[w] = 0.64 * (w < 6 ? plan(w - 2) : sales(w - 2));   // first six weeks of POs are already committed
    L.frt[w] = 0.045 * sales(w);
    L.opx[w] = 58 + (w >= 4 ? D.hires * 1.5 : 0);
  }
  [0, 2, 4, 6, 8, 10, 12].forEach(w => L.pay[w] = 386 + (w >= 4 ? D.hires * 5.4 : 0));
  [4, 8, 12].forEach(w => L.rent[w] = 142);
  L.tax[2] = 88; L.tax[6] = 92; L.tax[10] = 290; L.tax[11] = 104;
  L.debt[3] = 31; L.debt[8] = 31; L.debt[12] = 281;
  L.opx[5] += 132; L.oth[2] = 86;
  if (!D.defer) L.cap[6] = 420;
  if (D.rev) L.fin[6] = 1000;
  for (const k in L) L[k] = L[k].map(Math.round);
  const rec = [], dis = [], net = [], open = [], close = [], lo = [], hi = [];
  let bal = OPEN;
  for (let w = 0; w < 13; w++) {
    let r = 0, d = 0;
    LINES.forEach(([k, , g]) => { if (g > 0) r += L[k][w]; else d += L[k][w]; });
    open.push(bal); rec.push(r); dis.push(d); net.push(r - d); bal += r - d; close.push(bal);
    const sd = Math.round(52 * Math.sqrt(w + 1) * (1 + Math.max(0, slip) / 30));
    lo.push(bal - sd); hi.push(bal + sd);
  }
  let min = Infinity, minW = 0; close.forEach((v, w) => { if (v < min) { min = v; minW = w; } });
  const bw = close.map((v, w) => v < COV ? w : -1).filter(w => w >= 0);
  return { L, rec, dis, net, open, close, lo, hi, min, minW, breaches: bw, slip };
}

/* ------------------------------------------------------------------ state */
const D0 = { slip: 0, hires: 0, defer: false, rev: false };
const S = { view: 'forecast', sc: 'base', D: { ...D0 }, week: null, pinned: false, hover: null };
let M = model(S.sc, S.D), shown = null;

/* ------------------------------------------------------------------ tooltip */
const tip = $('.dbf-cashflow__tip');
function showTip(html, x, y) {
  tip.innerHTML = html; tip.classList.add('on');
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let l = x - r.left + 16, t = y - r.top - h / 2;
  if (l + w > r.width - 8) l = x - r.left - w - 16;
  l = Math.max(8, l); t = Math.max(8, Math.min(t, r.height - h - 8));
  tip.style.translate = Math.round(l) + 'px ' + Math.round(t) + 'px';
}
const hideTip = () => tip.classList.remove('on');

/* ------------------------------------------------------------------ number tween */
function tweenText(el, to, fmt) {
  const from = el._v == null ? to : el._v; el._v = to;
  if (RM || from === to) { el.textContent = fmt(to); return; }
  const t0 = performance.now();
  const step = now => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / 600), e = 1 - Math.pow(1 - k, 4);
    el.textContent = fmt(from + (to - from) * e);
    if (k < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* ------------------------------------------------------------------ KPIs */
const kpis = $('.dbf-cashflow__kpis');
kpis.innerHTML = ['Opening cash', 'Week 13 close', 'Lowest point', 'Covenant headroom'].map((t, i) => `<div style="--i:${i}"><dt>${t}</dt><dd></dd><span></span></div>`).join('');
function renderKpis() {
  const k = $$(':scope > div', kpis), head = M.min - COV;
  tweenText(k[0].children[1], OPEN, fmtM);
  k[0].children[2].textContent = 'Two operating accounts, Oct 2';
  tweenText(k[1].children[1], M.close[12], fmtM);
  k[1].children[2].innerHTML = `<b class="${M.close[12] >= OPEN ? 'ok' : 'bad'}">${fmtS(M.close[12] - OPEN)}</b> over 13 weeks`;
  tweenText(k[2].children[1], M.min, fmtM);
  k[2].children[2].textContent = `Week of ${dl(wkDate(M.minW))} · P10 ${fmtM(M.lo[M.minW])}`;
  tweenText(k[3].children[1], head, fmtS);
  k[3].classList.toggle('alert', M.breaches.length > 0);
  k[3].children[2].innerHTML = M.breaches.length
    ? `<b class="bad">Below $1.5M in ${M.breaches.length} week${M.breaches.length > 1 ? 's' : ''}</b>, from ${dl(wkDate(M.breaches[0]))}`
    : `<b class="ok">Clear</b> of the $1.5M minimum`;
}

/* ------------------------------------------------------------------ main chart */
const plot = $('.dbf-cashflow__plot'), svg = $('.dbf-cashflow__svg');
let G = null, intro = true;
const el = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const a in attrs) e.setAttribute(a, attrs[a]); if (parent) parent.append(e); return e; };
function niceStep(span, n) { const raw = span / n, mag = Math.pow(10, Math.floor(Math.log10(raw))), r = raw / mag; return (r <= 1 ? 1 : r <= 2 ? 2 : r <= 2.5 ? 2.5 : r <= 5 ? 5 : 10) * mag; }
function domainFor(m) {
  const lo = Math.min(0, ...m.lo), hi = Math.max(4000, OPEN, ...m.hi);
  const st = niceStep(hi - lo, 4);
  const flow = Math.max(1500, ...m.rec, ...m.dis), fs = niceStep(flow, 2);
  return { lo: Math.floor(lo / st) * st, hi: Math.ceil(hi / st) * st, st, fmax: Math.ceil(flow / fs) * fs };
}
function build() {
  const W = plot.clientWidth, H = plot.clientHeight; if (!W || !H) return false;
  const dom = domainFor(M);
  const L = 50, R = 10, y0 = 10, y1 = Math.round(H * 0.6), y2 = y1 + 26, y3 = H - 22, bw = (W - L - R) / 13;
  const ty = v => y1 - (v - dom.lo) / (dom.hi - dom.lo) * (y1 - y0);
  const zy = (y2 + y3) / 2, fy = v => zy - v / dom.fmax * (y3 - y2) / 2;
  svg.setAttribute('viewBox', `0 0 ${W} ${H}`);
  svg.replaceChildren();
  const grid = el('g', {}, svg);
  for (let v = dom.lo; v <= dom.hi + 1; v += dom.st) {
    el('line', { class: 'gl' + (v === 0 ? ' z' : ''), x1: L, x2: W - R, y1: ty(v), y2: ty(v) }, grid);
    el('text', { x: L - 8, y: ty(v) + 3.5, 'text-anchor': 'end' }, grid).textContent = v === 0 ? '$0' : fmtM(v).replace('.00', '');
  }
