.dbf-cards {
  /* re-theme with these four */
  --dbf-cards-bg: oklch(0.968 0.006 255);
  --dbf-cards-ink: oklch(0.24 0.03 262);
  --dbf-cards-accent: oklch(0.52 0.19 262);
  --dbf-cards-bad: oklch(0.58 0.19 27);
  /* derived */
  --dbf-cards-warn: oklch(from var(--dbf-cards-bad) calc(l + 0.12) c 62);
  --dbf-cards-good: oklch(from var(--dbf-cards-accent) 0.58 0.12 158);
  --dbf-cards-card: color-mix(in oklch, var(--dbf-cards-bg) 25%, white);
  --dbf-cards-line: color-mix(in oklch, var(--dbf-cards-ink) 10%, transparent);
