/* ---------------------------------------------------------------- sidebar */
.dbf-cards__side { display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; overflow: auto; scrollbar-width: thin; border-right: 1px solid var(--dbf-cards-line); }
