  & .bar i { display: block; height: 100%; width: calc(min(1, var(--u)) * 100%); border-radius: inherit; background: var(--dbf-cards-accent); transition: width .6s var(--dbf-cards-out); }
  & .bar i.hot { background: var(--dbf-cards-warn); }
