}

/* ---------------------------------------------------------------- center: card + limit + controls */
.dbf-cards__center { grid-area: center; min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 18px 20px 18px; display: grid; align-content: start; gap: 14px; }
