}
.dbf-cards__warn { font-size: 11.5px; color: color-mix(in oklch, var(--dbf-cards-bad) 85%, var(--dbf-cards-ink)); min-height: 0; text-wrap: pretty; &:empty { display: none; } }
.dbf-cards__acts {
