/* ---------------------------------------------------------------- right: scheduled + posted */
.dbf-cards__right { grid-area: right; min-width: 0; min-height: 0; overflow: auto; scrollbar-width: thin; border-left: 1px solid var(--dbf-cards-line); padding: 14px 14px 16px; background: color-mix(in oklch, var(--dbf-cards-bg), white 35%); }
.dbf-cards__rh {
