.dbf-cards__sched, .dbf-cards__posted {
  list-style: none; display: grid; gap: 4px;
  & li { display: grid; grid-template-columns: 40px minmax(0, 1fr) auto; gap: 1px 10px; align-items: center; padding: 7px 8px; border-radius: 10px; animation: dbf-cards-rise .45s var(--dbf-cards-out) both; animation-delay: calc(var(--i) * 30ms); }
  & .d { grid-row: 1 / 3; font: 600 11px/1.15 var(--dbf-cards-mono); color: var(--dbf-cards-mute); text-align: center; text-transform: uppercase; }
