  & .st { padding: 1px 7px; border-radius: 6px; color: color-mix(in oklch, var(--dbf-cards-good) 80%, black); background: color-mix(in oklch, var(--dbf-cards-good) 14%, transparent); }
  &.no { background: color-mix(in oklch, var(--dbf-cards-bad) 5%, var(--dbf-cards-card)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbf-cards-bad) 30%, transparent); }
  &.no .st { color: var(--dbf-cards-bad); background: color-mix(in oklch, var(--dbf-cards-bad) 12%, transparent); }
  &.no .a { color: var(--dbf-cards-mute); text-decoration: line-through; }
