}
@supports (animation-timeline: view()) {
  .dbf-cards__posted li { animation: dbf-cards-in linear both; animation-timeline: view(); animation-range: entry 0% entry 80%; }
}

/* ---------------------------------------------------------------- activity + limits views */
.dbf-cards__av, .dbf-cards__mv { grid-template-rows: auto minmax(0, 1fr); padding: 18px 20px 14px; gap: 12px; }
.dbf-cards__ah {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; flex-wrap: wrap;
  & h2 { font-size: 20px; font-weight: 750; letter-spacing: -.035em; }
  & h2 small { font-size: 12.5px; font-weight: 500; letter-spacing: 0; color: var(--dbf-cards-mute); margin-left: 6px; }
