radio($('.dbf-cards__lh .dbf-cards__filter'), 'f', v => { S.filter = v; renderList(); });

/* ------------------------------------------------------------------ the card */
const cardEl = $('.dbf-cards__card'), stage = $('.dbf-cards__stage');
