  $('.dbf-cards__who p').textContent = `${c.role} · ${c.team}${c.note ? ' · ' + c.note : ''}`;
  const fb = $('.dbf-cards__freeze'); fb.setAttribute('aria-pressed', c.frozen); $('span', fb).textContent = c.frozen ? 'Unfreeze card' : 'Freeze card';
