  $('.dbf-cards__sws').innerHTML = [['online', 'Online'], ['instore', 'In store'], ['atm', 'ATM cash'], ['intl', 'International']].map(([k, n]) =>
    `<button type="button" class="dbf-cards__sw" role="switch" aria-checked="${!!c.ch[k]}" data-k="${k}"${c.kind === 'virtual' && (k === 'instore' || k === 'atm') ? ' disabled title="Virtual cards cannot be used in store"' : ''}>${n}<i></i></button>`).join('');
