radio($('.dbf-cards__av .dbf-cards__filter'), 'st', v => { S.st = v; renderActivity(); });
tbl.addEventListener('click', e => { const tr = e.target.closest('tbody tr'); if (tr) { const i = +tr.dataset.i; go('cards'); choose(i); } });
