css:
.dbf-budget {
  /* re-theme with these four */
  --dbf-budget-bg: oklch(0.99 0.003 100);
  --dbf-budget-ink: oklch(0.21 0.012 270);
  --dbf-budget-marker: oklch(0.93 0.16 104);
  --dbf-budget-over: oklch(0.57 0.2 27);
  /* derived */
  --dbf-budget-under: oklch(from var(--dbf-budget-over) 0.55 0.1 165);
  --dbf-budget-paper: color-mix(in oklch, var(--dbf-budget-bg), var(--dbf-budget-ink) 2.5%);
  --dbf-budget-line: color-mix(in oklch, var(--dbf-budget-ink) 11%, transparent);
  --dbf-budget-hair: color-mix(in oklch, var(--dbf-budget-ink) 6%, transparent);
  --dbf-budget-soft: color-mix(in oklch, var(--dbf-budget-ink) 4.5%, transparent);
  --dbf-budget-mute: color-mix(in oklch, var(--dbf-budget-ink) 58%, var(--dbf-budget-bg));
  --dbf-budget-faint: color-mix(in oklch, var(--dbf-budget-ink) 38%, var(--dbf-budget-bg));
  --dbf-budget-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-budget-serif: ui-serif, "New York", Georgia, "Times New Roman", serif;
  --dbf-budget-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-budget-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-budget-inout: cubic-bezier(.65, 0, .35, 1);
  width: 100%;
  height: var(--dbf-budget-h, 680px);
  container-type: inline-size; container-name: dbf-budget;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 16px;
  background: var(--dbf-budget-bg);
  color: var(--dbf-budget-ink);
  font: 13px/1.45 var(--dbf-budget-sans);
  accent-color: var(--dbf-budget-ink);
  box-shadow: inset 0 0 0 1px var(--dbf-budget-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, ol, ul) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :where(textarea) { font: inherit; color: inherit; }
  & :focus-visible { outline: 2px solid var(--dbf-budget-ink); outline-offset: 2px; border-radius: 5px; }
}
.dbf-budget__shell { height: 100%; display: flex; flex-direction: column; padding: 0 20px 16px; gap: 12px; }

/* ---------------------------------------------------------------- top bar */
.dbf-budget__top { display: flex; align-items: center; gap: 18px; height: 50px; flex: none; border-bottom: 1px solid var(--dbf-budget-ink); }
.dbf-budget__brand {
  display: flex; align-items: center; gap: 8px; font-size: 13.5px; white-space: nowrap;
  & svg { width: 22px; height: 22px; fill: var(--dbf-budget-marker); stroke: var(--dbf-budget-ink); stroke-width: 1.6; stroke-linejoin: round; stroke-linecap: round; }
  & b { font-weight: 780; letter-spacing: -.02em; }
}
.dbf-budget__nav {
  display: flex; gap: 2px; height: 100%;
  & button { position: relative; padding: 0 12px; font-weight: 600; color: var(--dbf-budget-mute); display: inline-flex; align-items: center; gap: 6px; transition: color .2s; }
  & button:hover { color: var(--dbf-budget-ink); }
  & button::after { content: ""; position: absolute; left: 10px; right: 10px; bottom: -1px; height: 3px; background: var(--dbf-budget-ink); scale: 0 1; transition: scale .35s var(--dbf-budget-out); }
  & button[aria-current="page"] { color: var(--dbf-budget-ink); }
  & button[aria-current="page"]::after { scale: 1 1; }
}
.dbf-budget__badge { min-width: 18px; height: 18px; padding: 0 5px; border-radius: 9px; background: var(--dbf-budget-marker); color: var(--dbf-budget-ink); font-size: 10.5px; font-weight: 750; display: inline-grid; place-items: center; font-variant-numeric: tabular-nums; &:empty { display: none; } }
.dbf-budget__stamp { margin-left: auto; font: 11px var(--dbf-budget-mono); color: var(--dbf-budget-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

/* ---------------------------------------------------------------- title + period */
.dbf-budget__bar { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px 24px; flex-wrap: wrap; flex: none; }
.dbf-budget__title {
  min-width: 0;
  & h2 { font: 500 clamp(21px, 2.6cqi, 30px)/1.08 var(--dbf-budget-serif); letter-spacing: -.02em; text-wrap: balance; }
  & h2 em { font-style: normal; position: relative; z-index: 0; white-space: nowrap; }
  & h2 em::before { content: ""; position: absolute; z-index: -1; inset: .12em -.12em .02em -.14em; background: var(--dbf-budget-marker); border-radius: .2em .5em .3em .45em; rotate: -.6deg; clip-path: inset(0 100% 0 0); animation: dbf-budget-swipe .7s var(--dbf-budget-inout) .35s forwards; }
  & h2 em.u::before { background: color-mix(in oklch, var(--dbf-budget-under) 26%, var(--dbf-budget-bg)); }
}
.dbf-budget__sub { color: var(--dbf-budget-mute); margin-top: 4px; font-variant-numeric: tabular-nums; text-wrap: pretty; }
.dbf-budget__period { display: flex; align-items: flex-end; gap: 10px; flex-wrap: wrap; }
.dbf-budget__quick {
  display: flex; gap: 2px;
  & button { padding: 4px 8px; border-radius: 6px; font-size: 11.5px; font-weight: 650; color: var(--dbf-budget-mute); transition: background-color .15s, color .15s; }
  & button:hover { color: var(--dbf-budget-ink); background: var(--dbf-budget-soft); }
  & button[aria-pressed="true"] { color: var(--dbf-budget-bg); background: var(--dbf-budget-ink); }
}
.dbf-budget__months {
  display: grid; grid-template-columns: repeat(12, 34px); gap: 2px; padding: 3px; border-radius: 10px; background: var(--dbf-budget-soft);
  & [role="option"] {
    position: relative; height: 40px; border-radius: 7px; display: grid; grid-template-rows: 1fr auto; justify-items: center; padding: 4px 0 3px; cursor: pointer;
    font-size: 11px; font-weight: 650; color: var(--dbf-budget-mute); transition: background-color .2s, color .2s;
  }
  & [role="option"]:hover { color: var(--dbf-budget-ink); }
  & [role="option"] i { align-self: end; width: 4px; border-radius: 2px; height: calc(var(--m) * 16px + 2px); background: var(--dbf-budget-faint); }
  & [role="option"] i.o { background: var(--dbf-budget-over); }
  & [role="option"] i.u { background: var(--dbf-budget-under); }
  & [aria-selected="true"] { background: var(--dbf-budget-bg); color: var(--dbf-budget-ink); box-shadow: 0 1px 2px color-mix(in oklch, var(--dbf-budget-ink) 20%, transparent); }
  & [aria-disabled="true"] { cursor: not-allowed; color: var(--dbf-budget-faint); background: repeating-linear-gradient(-45deg, transparent 0 4px, var(--dbf-budget-hair) 4px 5px); }
  & [aria-disabled="true"] i { opacity: .45; }
}

/* ---------------------------------------------------------------- views */
.dbf-budget__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  transition: opacity .35s var(--dbf-budget-out), translate .5s var(--dbf-budget-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-budget__vv { grid-template-rows: 196px minmax(0, 1fr); }
.dbf-budget__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; position: relative;
  border-top: 1px solid var(--dbf-budget-line);
  animation: dbf-budget-rise .7s var(--dbf-budget-out) both; animation-delay: calc(var(--i, 0) * 80ms + 60ms);
}
.dbf-budget__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 9px 0 4px; flex-wrap: wrap;
  & h3 { font-size: 11px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
}
.dbf-budget__key {
  list-style: none; display: flex; gap: 12px; font-size: 11px; color: var(--dbf-budget-mute);
  & li { display: inline-flex; align-items: center; gap: 5px; }
