  & .ac { position: absolute; left: 0; top: 5px; bottom: 5px; width: calc(var(--a) * 100%); border-radius: 1px; background: var(--dbf-budget-ink); transform-origin: 0 50%; transition: width .6s var(--dbf-budget-out); animation: dbf-budget-growx .8s var(--dbf-budget-out) both; animation-delay: calc(var(--i, 0) * 50ms + 200ms); }
