}

@keyframes dbf-budget-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbf-budget-fade { from { opacity: 0; } }
@keyframes dbf-budget-grow { from { transform: scaleY(0); } }
@keyframes dbf-budget-growx { from { transform: scaleX(0); } }
