@keyframes dbf-budget-flash { 0%, 40% { background: color-mix(in oklch, var(--dbf-budget-marker) 60%, transparent); } }

/* ---------------------------------------------------------------- container responsive */
@container dbf-budget (width < 1000px) {
  .dbf-budget__stamp { display: none; }
