function flagged() { return G.rows.flatMap(r => r.ls).filter(x => Math.abs(x.P) >= 0.05 && Math.abs(x.V) >= 10000).sort((a, b) => Math.abs(b.V) - Math.abs(a.V)); }
function renderBadge() { const f = flagged(), left = f.filter(x => !DONE.has(x.L.id)).length; $('.dbf-budget__badge').textContent = left || ''; return f; }
function renderNotes() {
  const f = renderBadge(), done = f.filter(x => DONE.has(x.L.id)).length;
  $('.dbf-budget__prog').innerHTML = `${done} of ${f.length} explained · ${esc(pname())}<i><b style="--p:${f.length ? done / f.length : 1}"></b></i>`;
  notes.innerHTML = f.map((x, k) => `<li style="--i:${k}" data-l="${x.L.id}" class="${DONE.has(x.L.id) ? 'done' : ''}"><div><b>${esc(x.L.n)}</b><small>${esc(x.L.d.n)} · owner ${esc(x.L.d.own)}</small></div>
    <div class="vv ${x.V > 0 ? 'o' : 'u'}">${fs(x.V)}<small>${pc(x.P)} of ${fm(x.B)}</small></div>
    <textarea rows="1" aria-label="Explanation for ${esc(x.L.d.n)} ${esc(x.L.n)}" placeholder="Why is ${esc(x.L.n.toLowerCase())} ${x.V > 0 ? 'over' : 'under'} plan?">${esc(NOTES[x.L.id] || '')}</textarea>
    <button type="button" aria-pressed="${DONE.has(x.L.id)}">${DONE.has(x.L.id) ? 'Explained' : 'Mark explained'}</button></li>`).join('') || '<li><span class="empty">Nothing over threshold in this period.</span></li>';
}
notes.addEventListener('input', e => { const li = e.target.closest('li[data-l]'); if (li && e.target.tagName === 'TEXTAREA') NOTES[li.dataset.l] = e.target.value; });
notes.addEventListener('click', e => {
  const b = e.target.closest('button'); if (!b) return;
  const li = b.closest('li[data-l]'), id = li.dataset.l;
  if (DONE.has(id)) DONE.delete(id); else { if (!(NOTES[id] || '').trim()) { const ta = $('textarea', li); ta.focus(); ta.animate([{ transform: 'translateX(-4px)' }, { transform: 'translateX(4px)' }, { transform: 'none' }], { duration: 260, iterations: 2 }); return; } DONE.add(id); }
  li.classList.toggle('done', DONE.has(id)); b.setAttribute('aria-pressed', DONE.has(id)); b.textContent = DONE.has(id) ? 'Explained' : 'Mark explained';
  const f = flagged(), done = f.filter(x => DONE.has(x.L.id)).length;
  $('.dbf-budget__prog').innerHTML = `${done} of ${f.length} explained · ${esc(pname())}<i><b style="--p:${f.length ? done / f.length : 1}"></b></i>`;
  renderBadge();
});

/* ------------------------------------------------------------------ views */
function render() {
  hideTip();
  if (S.view === 'var') { renderBridge(); renderTable(); }
  else if (S.view === 'trend') renderTrend();
  else renderNotes();
}
function go(v) {
  S.view = v;
  $$('.dbf-budget__nav button').forEach(b => b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current'));
  $$('.dbf-budget__view').forEach(x => x.hidden = x.dataset.view !== v);
  render();
}
$('.dbf-budget__nav').addEventListener('click', e => { const b = e.target.closest('[data-view]'); if (b) go(b.dataset.view); });
$('.dbf-budget__nav').addEventListener('keydown', e => {
  const bs = $$('.dbf-budget__nav button'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  const j = e.key === 'ArrowRight' ? (i + 1) % bs.length : e.key === 'ArrowLeft' ? (i - 1 + bs.length) % bs.length : -1;
  if (j >= 0) { e.preventDefault(); bs[j].focus(); }
});

/* ------------------------------------------------------------------ mount */
S.open.add(G.rows.slice().sort((a, b) => b.V - a.V)[0].d.i);
syncMonths(); renderTitle(); renderBadge(); renderTable();
let bs = '', ts = '';
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const k1 = bplot.clientWidth + 'x' + bplot.clientHeight, k2 = tplot.clientWidth + 'x' + tplot.clientHeight;
  if (S.view === 'var' && k1 !== bs && bplot.clientWidth) { bs = k1; renderBridge(); }
  if (S.view === 'trend' && k2 !== ts && tplot.clientWidth) { ts = k2; renderTrend(); }
});
ro.observe(bplot); ro.observe(tplot);

css:
.dbf-ar {
  /* re-theme with these four: the ageing ramp is mixed from cool to hot */
  --dbf-ar-bg: oklch(0.972 0.016 84);
  --dbf-ar-ink: oklch(0.27 0.035 52);
  --dbf-ar-cool: oklch(0.7 0.075 152);
  --dbf-ar-hot: oklch(0.52 0.17 28);
  /* derived */
  --dbf-ar-r0: var(--dbf-ar-cool);
  --dbf-ar-r1: color-mix(in oklch, var(--dbf-ar-cool) 62%, oklch(0.88 0.14 98));
  --dbf-ar-r2: color-mix(in oklch, var(--dbf-ar-hot) 30%, oklch(0.84 0.14 80));
  --dbf-ar-r3: color-mix(in oklch, var(--dbf-ar-hot) 65%, oklch(0.78 0.15 60));
  --dbf-ar-r4: var(--dbf-ar-hot);
  --dbf-ar-card: color-mix(in oklch, var(--dbf-ar-bg) 45%, white);
  --dbf-ar-line: color-mix(in oklch, var(--dbf-ar-ink) 12%, transparent);
  --dbf-ar-rule: color-mix(in oklch, var(--dbf-ar-ink) 7%, transparent);
  --dbf-ar-soft: color-mix(in oklch, var(--dbf-ar-ink) 5%, transparent);
  --dbf-ar-mute: color-mix(in oklch, var(--dbf-ar-ink) 62%, var(--dbf-ar-bg));
  --dbf-ar-faint: color-mix(in oklch, var(--dbf-ar-ink) 40%, var(--dbf-ar-bg));
  --dbf-ar-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-ar-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-ar-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-ar-spring: linear(0, 0.06 1.5%, 0.24 3.6%, 0.75 9.5%, 0.96 13%, 1.06 16.5%, 1.08 19.5%, 1.05 24%, 1 31%, 0.992 40%, 1);
  width: 100%;
  height: var(--dbf-ar-h, 680px);
  container-type: inline-size; container-name: dbf-ar;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbf-ar-bg);
  color: var(--dbf-ar-ink);
  font: 13px/1.45 var(--dbf-ar-sans);
  accent-color: var(--dbf-ar-ink);
  box-shadow: inset 0 0 0 1px var(--dbf-ar-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbf-ar-ink); outline-offset: 2px; border-radius: 5px; }
  & input[type="checkbox"] { width: 15px; height: 15px; margin: 0; cursor: pointer; }
}
.dbf-ar__ic { width: 17px; height: 17px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-ar__shell { height: 100%; display: grid; grid-template-columns: 76px minmax(0, 1fr); }

/* ---------------------------------------------------------------- rail */
.dbf-ar__side { display: flex; flex-direction: column; align-items: center; gap: 6px; padding: 18px 8px 14px; min-height: 0; background: var(--dbf-ar-ink); color: var(--dbf-ar-bg); }
.dbf-ar__brand {
  display: grid; justify-items: center; gap: 4px; padding-bottom: 14px; margin-bottom: 4px; border-bottom: 1px solid color-mix(in oklch, var(--dbf-ar-bg) 18%, transparent); width: 100%;
  & svg { width: 28px; height: 28px; fill: none; stroke: var(--dbf-ar-r2); stroke-width: 1.8; stroke-linejoin: round; stroke-linecap: round; }
  & b { display: block; font-size: 10.5px; font-weight: 750; letter-spacing: .02em; text-align: center; }
  & small { display: none; }
}
.dbf-ar__nav { display: grid; gap: 4px; width: 100%; }
.dbf-ar__item {
  display: grid; justify-items: center; gap: 3px; padding: 9px 4px 7px; border-radius: 10px; font-size: 10.5px; font-weight: 600; color: color-mix(in oklch, var(--dbf-ar-bg) 62%, transparent);
  transition: background-color .2s, color .2s;
  & .dbf-ar__ic { width: 20px; height: 20px; }
  &:hover { color: var(--dbf-ar-bg); background: color-mix(in oklch, var(--dbf-ar-bg) 8%, transparent); }
  &[aria-current="page"] { color: var(--dbf-ar-ink); background: var(--dbf-ar-bg); }
  &:focus-visible { outline-color: var(--dbf-ar-bg); }
}
.dbf-ar__foot { margin-top: auto; font-size: 10px; color: color-mix(in oklch, var(--dbf-ar-bg) 55%, transparent); text-align: center; display: none; }

/* ---------------------------------------------------------------- main */
.dbf-ar__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 16px 18px 16px; }
.dbf-ar__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap;
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 760; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance; }
}
.dbf-ar__eyebrow { font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbf-ar-faint); margin-bottom: 2px; }
.dbf-ar__asof {
  display: inline-flex; align-items: center; gap: 2px; padding: 3px; border-radius: 10px; background: var(--dbf-ar-soft); box-shadow: inset 0 0 0 1px var(--dbf-ar-line);
  & span { font-size: 11.5px; color: var(--dbf-ar-mute); padding: 0 6px 0 8px; }
  & button { padding: 5px 10px; border-radius: 7px; font-size: 12.5px; font-weight: 650; font-variant-numeric: tabular-nums; color: var(--dbf-ar-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dbf-ar-ink); }
  & button[aria-checked="true"] { background: var(--dbf-ar-ink); color: var(--dbf-ar-bg); }
}
.dbf-ar__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  transition: opacity .35s var(--dbf-ar-out), translate .5s var(--dbf-ar-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-ar__av {
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.22fr);
  grid-template-rows: auto auto minmax(0, 1fr);
  grid-template-areas: "kpis kpis" "strip strip" "mx inv";
}
.dbf-ar__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; position: relative;
  background: var(--dbf-ar-card); border-radius: 14px; box-shadow: inset 0 0 0 1px var(--dbf-ar-line);
  animation: dbf-ar-rise .7s var(--dbf-ar-out) both; animation-delay: calc(var(--i, 0) * 80ms + 150ms);
}
.dbf-ar__ph { display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 14px 7px; min-height: 42px; flex-wrap: wrap; & h3 { font-size: 12.5px; font-weight: 700; } }
.dbf-ar__hint { font-size: 11.5px; color: var(--dbf-ar-faint); }
.dbf-ar__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbf-ar-ink) 22%, transparent) transparent; }

/* ---------------------------------------------------------------- KPIs */
.dbf-ar__kpis {
  grid-area: kpis; display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 0;
  border-top: 1px solid var(--dbf-ar-ink); border-bottom: 1px solid var(--dbf-ar-line);
  & > div { padding: 9px 14px 10px; border-left: 1px solid var(--dbf-ar-line); animation: dbf-ar-rise .6s var(--dbf-ar-out) both; animation-delay: calc(var(--i) * 50ms); }
  & > div:first-child { border-left: 0; padding-left: 2px; }
  & dt { font-size: 11px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--dbf-ar-faint); }
  & dd { font-size: clamp(18px, 2.2cqi, 24px); font-weight: 760; letter-spacing: -.035em; font-variant-numeric: tabular-nums; line-height: 1.2; white-space: nowrap; }
  & dd small { display: block; font-size: 11.5px; font-weight: 550; letter-spacing: 0; color: var(--dbf-ar-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .up { color: var(--dbf-ar-r4); }
  & .dn { color: color-mix(in oklch, var(--dbf-ar-cool) 70%, black); }
}

/* ---------------------------------------------------------------- ageing strip */
.dbf-ar__strip {
  grid-area: strip; display: flex; gap: 3px; height: 54px;
  & button {
    position: relative; flex: var(--w) 1 0; min-width: 52px; border-radius: 8px; padding: 6px 9px; text-align: left; overflow: hidden;
    background: var(--c); color: color-mix(in oklch, var(--c) 18%, black);
    display: grid; align-content: space-between;
    transition: flex-grow .6s var(--dbf-ar-spring), filter .2s, opacity .25s, box-shadow .2s;
    animation: dbf-ar-wipe .8s var(--dbf-ar-out) both; animation-delay: calc(var(--i) * 70ms + 100ms);
  }
  & button:nth-child(n+4) { color: white; }
  & b { font-size: 10.5px; font-weight: 750; letter-spacing: .05em; text-transform: uppercase; white-space: nowrap; }
  & span { font-size: 15px; font-weight: 760; letter-spacing: -.02em; font-variant-numeric: tabular-nums; white-space: nowrap; }
  & span small { font-size: 11px; font-weight: 600; opacity: .75; margin-left: 4px; }
  & button:hover { filter: brightness(1.05) saturate(1.1); }
  &:has(button[aria-pressed="true"]) button:not([aria-pressed="true"]) { opacity: .38; filter: saturate(.5); }
  & button[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--dbf-ar-ink); }
}

/* ---------------------------------------------------------------- customer x bucket matrix */
.dbf-ar__mxp { grid-area: mx; --i: 1; }
.dbf-ar__mx {
  width: 100%; border-collapse: separate; border-spacing: 0 2px; font-size: 12px; padding: 0 8px 8px;
  & th { font-size: 9.5px; font-weight: 700; letter-spacing: .03em; text-transform: uppercase; color: var(--dbf-ar-faint); padding: 0 4px 4px; text-align: right; white-space: nowrap; position: sticky; top: 0; background: var(--dbf-ar-card); z-index: 1; }
  & th:first-child { text-align: left; }
  & th i { display: block; height: 3px; border-radius: 2px; background: var(--c); margin-top: 4px; }
  & tbody th { position: static; font-size: 12px; font-weight: 600; letter-spacing: 0; text-transform: none; color: var(--dbf-ar-ink); text-align: left; overflow: hidden; text-overflow: ellipsis; padding: 0 6px 0 4px; max-width: 150px; }
  & td { padding: 0 1px; }
  & td button {
    width: 100%; height: 28px; border-radius: 5px; padding: 0 6px; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; font-size: 11.5px;
    background: oklch(from var(--c) l c h / calc(0.1 + var(--v) * 0.9)); color: var(--dbf-ar-ink);
    transition: box-shadow .15s, scale .25s var(--dbf-ar-out);
    animation: dbf-ar-pop .45s var(--dbf-ar-out) both; animation-delay: calc(var(--i) * 12ms + 250ms);
  }
  & td button.hot { color: white; }
  & td button:hover { box-shadow: inset 0 0 0 1.5px var(--dbf-ar-ink); }
  & td button[aria-pressed="true"] { box-shadow: inset 0 0 0 2px var(--dbf-ar-ink); scale: 1.05; }
  & td .z { display: block; text-align: right; color: var(--dbf-ar-faint); padding-right: 6px; font-size: 11px; }
  & td.t { text-align: right; font-weight: 750; font-variant-numeric: tabular-nums; padding-right: 4px; }
  & tbody tr:has(button[aria-pressed="true"]) th { text-decoration: underline; text-underline-offset: 3px; }
  & tfoot td, & tfoot th { border-top: 1px solid var(--dbf-ar-ink); padding-top: 6px; font-weight: 750; text-align: right; font-variant-numeric: tabular-nums; }
  & tfoot th { text-align: left; position: static; color: var(--dbf-ar-ink); }
}

/* ---------------------------------------------------------------- invoices */
.dbf-ar__invp { grid-area: inv; --i: 2; }
.dbf-ar__invh { position: relative; }
.dbf-ar__filters {
  display: flex; align-items: center; gap: 6px; flex-wrap: wrap; min-height: 26px; font-size: 12.5px; font-weight: 700;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 3px 6px 3px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 650; background: var(--dbf-ar-soft); box-shadow: inset 0 0 0 1px var(--dbf-ar-line); }
  & button svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
  & button:hover { box-shadow: inset 0 0 0 1px var(--dbf-ar-ink); }
  & i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & span { font-weight: 500; color: var(--dbf-ar-mute); font-size: 11.5px; font-variant-numeric: tabular-nums; }
}
.dbf-ar__bulk {
  position: absolute; inset: 6px 8px; display: flex; align-items: center; gap: 4px; padding: 0 8px; border-radius: 10px;
  background: var(--dbf-ar-ink); color: var(--dbf-ar-bg); opacity: 0; translate: 0 -6px; pointer-events: none; visibility: hidden;
  transition: opacity .2s, translate .35s var(--dbf-ar-spring), visibility 0s .2s;
  & .dbf-ar__selc { font-size: 12px; font-weight: 700; margin-right: auto; font-variant-numeric: tabular-nums; }
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border-radius: 7px; font-size: 12px; font-weight: 650; transition: background-color .15s; }
  & button:hover { background: color-mix(in oklch, var(--dbf-ar-bg) 14%, transparent); }
  & button.q { color: color-mix(in oklch, var(--dbf-ar-bg) 65%, transparent); }
  & button:focus-visible { outline-color: var(--dbf-ar-bg); }
}
.dbf-ar__invp:has(tbody input:checked) .dbf-ar__bulk { opacity: 1; translate: 0 0; pointer-events: auto; visibility: visible; transition: opacity .2s, translate .35s var(--dbf-ar-spring), visibility 0s; }
.dbf-ar__inv {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbf-ar-card); text-align: left; padding: 0 8px; height: 32px; font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--dbf-ar-faint); border-bottom: 1px solid var(--dbf-ar-line); white-space: nowrap; }
  & th.r, & td.r { text-align: right; }
  & th button { display: inline-flex; align-items: center; gap: 4px; letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & th button::after { content: ""; width: 6px; height: 6px; border: solid currentColor; border-width: 0 1.5px 1.5px 0; rotate: 45deg; translate: 0 -2px; opacity: 0; transition: rotate .25s var(--dbf-ar-out), opacity .2s; }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dbf-ar-ink); }
  & th[aria-sort="descending"] button::after { opacity: 1; }
  & th[aria-sort="ascending"] button::after { opacity: 1; rotate: 225deg; translate: 0 2px; }
  & .ck { width: 34px; padding-right: 0; }
  & td { padding: 0 7px; height: 38px; border-bottom: 1px solid var(--dbf-ar-rule); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & tbody tr { transition: background-color .15s; }
  & tbody tr:hover { background: var(--dbf-ar-soft); }
  & tbody tr:has(input:checked) { background: color-mix(in oklch, var(--dbf-ar-r1) 22%, transparent); }
  & .no { font-family: var(--dbf-ar-mono); font-size: 11.5px; color: var(--dbf-ar-mute); }
  & .cu { max-width: 150px; overflow: hidden; text-overflow: ellipsis; font-weight: 600; }
  & .late { display: inline-flex; align-items: center; gap: 6px; justify-content: flex-end; font-weight: 650; }
  & .late i { width: 8px; height: 8px; border-radius: 50%; background: var(--c); }
  & .mu { color: var(--dbf-ar-mute); }
  & .pill { display: inline-block; padding: 1px 7px; border-radius: 6px; font-size: 11px; font-weight: 700; background: var(--dbf-ar-soft); color: var(--dbf-ar-mute); }
  & .pill.rem { background: color-mix(in oklch, var(--dbf-ar-cool) 22%, transparent); color: color-mix(in oklch, var(--dbf-ar-cool) 60%, black); }
  & .pill.dis { background: color-mix(in oklch, var(--dbf-ar-hot) 14%, transparent); color: var(--dbf-ar-hot); }
  & .pill.new { animation: dbf-ar-pulse .9s var(--dbf-ar-out); }
  & .empty td { text-align: center; color: var(--dbf-ar-mute); height: 80px; }
}

/* ---------------------------------------------------------------- customers view */
.dbf-ar__cv { grid-template-rows: minmax(0, 1fr); }
.dbf-ar__cust {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbf-ar-card); text-align: left; padding: 0 10px; height: 36px; font-size: 10.5px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--dbf-ar-faint); border-bottom: 1px solid var(--dbf-ar-line); white-space: nowrap; }
  & th button { letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & th[aria-sort="descending"] button, & th[aria-sort="ascending"] button { color: var(--dbf-ar-ink); text-decoration: underline; text-underline-offset: 3px; }
  & .r { text-align: right; }
  & td { padding: 0 10px; height: 46px; border-bottom: 1px solid var(--dbf-ar-rule); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & tbody tr { cursor: pointer; transition: background-color .15s; animation: dbf-ar-rise .5s var(--dbf-ar-out) both; animation-delay: calc(var(--i) * 30ms); }
  & tbody tr:hover { background: var(--dbf-ar-soft); }
  & .nm b { display: block; font-weight: 650; }
  & .nm small { color: var(--dbf-ar-mute); font-size: 11.5px; }
  & .ut { display: grid; grid-template-columns: 90px auto; gap: 8px; align-items: center; }
  & .ut span { height: 6px; border-radius: 3px; background: var(--dbf-ar-soft); overflow: hidden; }
  & .ut span i { display: block; height: 100%; width: calc(min(1, var(--u)) * 100%); border-radius: inherit; background: var(--dbf-ar-ink); transform-origin: 0 50%; animation: dbf-ar-growx .8s var(--dbf-ar-out) both; animation-delay: calc(var(--i) * 30ms + 150ms); }
  & .ut span i.hot { background: var(--dbf-ar-hot); }
  & .mixb { display: flex; width: 120px; height: 10px; border-radius: 3px; overflow: hidden; gap: 1px; }
  & .mixb i { flex: var(--w) 1 0; background: var(--c); }
  & svg { width: 72px; height: 22px; display: block; overflow: visible; }
  & svg path { fill: none; stroke: var(--dbf-ar-ink); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }
  & svg circle { fill: var(--dbf-ar-ink); }
  & .risk { display: inline-block; padding: 1px 8px; border-radius: 6px; font-size: 11px; font-weight: 700; }
  & .risk.lo { background: color-mix(in oklch, var(--dbf-ar-cool) 22%, transparent); color: color-mix(in oklch, var(--dbf-ar-cool) 55%, black); }
  & .risk.md { background: color-mix(in oklch, var(--dbf-ar-r2) 35%, transparent); color: color-mix(in oklch, var(--dbf-ar-r3) 60%, black); }
  & .risk.hi { background: color-mix(in oklch, var(--dbf-ar-hot) 15%, transparent); color: var(--dbf-ar-hot); }
}

/* ---------------------------------------------------------------- tooltip + toast */
.dbf-ar__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 170px; padding: 8px 11px; border-radius: 9px;
  background: var(--dbf-ar-ink); color: var(--dbf-ar-bg); font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums;
  opacity: 0; scale: .96; transition: opacity .14s, scale .2s var(--dbf-ar-out);
  & b { display: block; }
  & span { display: flex; justify-content: space-between; gap: 14px; color: color-mix(in oklch, var(--dbf-ar-bg) 70%, transparent); }
  & em { font-style: normal; font-weight: 650; color: var(--dbf-ar-bg); }
  &.on { opacity: 1; scale: 1; }
}
.dbf-ar__toast {
  position: absolute; right: 18px; bottom: 18px; z-index: 40; padding: 10px 14px; border-radius: 10px; background: var(--dbf-ar-ink); color: var(--dbf-ar-bg); font-size: 12.5px; font-weight: 600;
  opacity: 0; translate: 0 12px; pointer-events: none; transition: opacity .25s, translate .45s var(--dbf-ar-spring);
  &.on { opacity: 1; translate: 0 0; }
}

@keyframes dbf-ar-rise { from { opacity: 0; transform: translateY(8px); } }
@keyframes dbf-ar-pop { from { opacity: 0; transform: scale(.8); } }
@keyframes dbf-ar-growx { from { transform: scaleX(0); } }
@keyframes dbf-ar-wipe { from { clip-path: inset(0 100% 0 0 round 8px); } to { clip-path: inset(0 0 0 0 round 8px); } }
@keyframes dbf-ar-pulse { 0% { scale: 1.25; } }

/* ---------------------------------------------------------------- responsive */
@container dbf-ar (width < 980px) {
  .dbf-ar__main { overflow: auto; scrollbar-width: thin; }
  .dbf-ar__view { flex: none; }
  .dbf-ar__av { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto auto 380px 440px; grid-template-areas: "kpis" "strip" "mx" "inv"; }
  .dbf-ar__cv { grid-template-rows: 520px; }
  .dbf-ar__strip span small { display: none; }
}
@container dbf-ar (width < 760px) {
  .dbf-ar__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dbf-ar__side { flex-direction: row; padding: 8px 12px; gap: 10px; }
  .dbf-ar__brand { display: flex; width: auto; padding: 0 10px 0 0; margin: 0; border-bottom: 0; border-right: 1px solid color-mix(in oklch, var(--dbf-ar-bg) 18%, transparent); & svg { width: 24px; height: 24px; } }
  .dbf-ar__nav { display: flex; width: auto; }
  .dbf-ar__item { grid-auto-flow: column; gap: 6px; padding: 7px 10px; font-size: 12px; }
  .dbf-ar__item .dbf-ar__ic { width: 17px; height: 17px; }
  .dbf-ar__main { overflow: auto; scrollbar-width: thin; padding: 12px; }
  .dbf-ar__view { flex: none; }
  .dbf-ar__cv { grid-template-rows: 480px; }
  .dbf-ar__kpis { grid-template-columns: repeat(2, minmax(0, 1fr)); & > div:nth-child(3) { border-left: 0; padding-left: 2px; } & > div:nth-child(n+3) { border-top: 1px solid var(--dbf-ar-line); } }
  .dbf-ar__strip { height: 46px; & span { font-size: 13px; } }
  .dbf-ar__hd, .dbf-ar__inv td:nth-child(4) { display: none; }
}
@container dbf-ar (width < 460px) {
  .dbf-ar__strip button { min-width: 0; padding: 5px 6px; }
  .dbf-ar__strip b { font-size: 9px; }
  .dbf-ar__strip span { font-size: 11.5px; }
  .dbf-ar__inv th:nth-child(2), .dbf-ar__inv td:nth-child(2) { display: none; }
  .dbf-ar__bulk button svg { display: none; }
  .dbf-ar__cust .dbf-ar__cx { display: none; }
  .dbf-ar__mx { min-width: 440px; }
}

@media (prefers-reduced-motion: reduce) {
  .dbf-ar__panel, .dbf-ar__kpis > div, .dbf-ar__strip button, .dbf-ar__mx td button, .dbf-ar__cust tbody tr, .dbf-ar__cust .ut span i, .dbf-ar__inv .pill.new { animation: none; }
  .dbf-ar__view, .dbf-ar__bulk, .dbf-ar__strip button, .dbf-ar__toast, .dbf-ar__tip { transition: none; }
}

