const $ = (s, el) => (el || root).querySelector(s);
const $$ = (s, el) => [...(el || root).querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)').matches;
const SPRING = 'linear(0, 0.06 1.5%, 0.24 3.6%, 0.75 9.5%, 0.96 13%, 1.06 16.5%, 1.08 19.5%, 1.05 24%, 1 31%, 0.992 40%, 1)';
function rng(a) { return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const R = rng(31);
const gauss = () => { let u = 0, v = 0; while (!u) u = R(); while (!v) v = R(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
const MON = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const NF = new Intl.NumberFormat('en-US', { maximumFractionDigits: 0 });
const usd = v => '$' + NF.format(Math.round(v));
const k = v => v >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : v >= 1e4 ? '$' + Math.round(v / 1e3) + 'k' : v >= 1e3 ? '$' + (v / 1e3).toFixed(1) + 'k' : '$' + Math.round(v);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const D0 = new Date(2026, 1, 1);                      // day 0 = Feb 1 2026
const dayOf = (m, d) => Math.round((new Date(2026, m, d) - D0) / 864e5);
const dateOf = n => new Date(2026, 1, 1 + n);
const dl = n => { const d = dateOf(n); return MON[d.getMonth()] + ' ' + d.getDate(); };
const ASOF = { jun: dayOf(5, 30), jul: dayOf(6, 31), aug: dayOf(7, 31), sep: dayOf(8, 30) };
const PREV = { jul: 'jun', aug: 'jul', sep: 'aug' };
const BK = [['Current', 'r0'], ['1–30', 'r1'], ['31–60', 'r2'], ['61–90', 'r3'], ['90+', 'r4']];
const bucket = late => late <= 0 ? 0 : late <= 30 ? 1 : late <= 60 ? 2 : late <= 90 ? 3 : 4;

/* ------------------------------------------------------------------ data: every invoice with issue, due and paid dates */
// name, terms, credit limit, mean days late, spread, invoices / month, amount range
const CUST = [
// the last number is the share of invoices that get stuck (short-shipped, missing PO, disputed) and stay open
  ['Vantor Data Centers', 30, 350000, 6, 4, 5, [9000, 46000], .02],
  ['Ridgeway Builders', 45, 400000, 22, 10, 4, [12000, 58000], .08],
  ['Ballast & Beam Contractors', 60, 500000, 12, 8, 3, [18000, 72000], .04],
  ['Juniper School District', 45, 200000, 30, 9, 2, [8000, 34000], .12],
  ['Corvel Hospital Group', 60, 300000, 5, 5, 3, [7000, 30000], .03],
  ['Halberd Mechanical', 30, 250000, 8, 6, 4, [4000, 26000], .04],
  ['Millrace Apartments', 30, 110000, 55, 18, 2, [3500, 19000], .3],
  ['Orrin Property Group', 30, 180000, 15, 10, 3, [3000, 17000], .07],
  ['Tamsin Electric', 30, 120000, 40, 14, 3, [2500, 15000], .2],
  ['Sablewood Homes', 45, 220000, 2, 5, 2, [6000, 28000], 0],
  ['Keel & Rudder Marine', 30, 60000, 9, 5, 2, [2000, 11000], 0],
  ['Northgate Facilities', 30, 150000, 0, 4, 3, [2000, 12000], 0],
  ['Esker Plumbing', 30, 75000, 18, 12, 3, [1200, 7800], .12],
  ['Prairie Line HVAC', 30, 90000, -3, 3, 2, [1500, 9000], 0]
];
const C = CUST.map(([n, terms, limit, lm, ls, pm, rg, stuck], i) => ({ i, n, terms, limit, lm, ls, pm, rg, stuck }));
let INV = [];
C.forEach(c => {
  const gap = 30 / c.pm;
  for (let d = R() * gap; d < ASOF.sep; d += gap * (0.6 + R() * 0.8)) {
    const issue = Math.floor(d), due = issue + c.terms, amt = Math.round((c.rg[0] + R() * (c.rg[1] - c.rg[0])) / 10) * 10;
    let paid = R() < c.stuck ? Infinity : due + Math.round(c.lm + gauss() * c.ls);
    if (c.n === 'Keel & Rudder Marine' && issue > dayOf(4, 20)) paid = Infinity;   // stopped paying after a warranty dispute
    paid = Math.max(issue + 3, paid);
    if (paid > ASOF.sep) paid = Infinity;                                          // not paid yet
    INV.push({ c: c.i, issue, due, amt, paid, st: 'open', stAt: null });
  }
});
INV.sort((a, b) => a.issue - b.issue || a.c - b.c);
INV.forEach((v, i) => { v.no = 'CL-' + (24180 + i); v.i = i; });
INV.filter(v => C[v.c].n === 'Keel & Rudder Marine' && v.paid === Infinity).slice(0, 2).forEach(v => { v.st = 'dis'; v.stAt = 'Jul 14'; });
INV.filter(v => C[v.c].n === 'Tamsin Electric' && v.paid === Infinity).slice(0, 1).forEach(v => { v.st = 'dis'; v.stAt = 'Sep 8'; });
INV.filter(v => C[v.c].n === 'Millrace Apartments' && v.paid === Infinity).slice(0, 2).forEach(v => { v.st = 'rem'; v.stAt = 'Sep 22'; });

/* ------------------------------------------------------------------ ageing as of a date */
function ageing(key) {
  const D = ASOF[key];
  const open = INV.filter(v => v.issue <= D && v.paid > D).map(v => ({ v, late: D - v.due, b: bucket(D - v.due) }));
  const tot = open.reduce((s, x) => s + x.v.amt, 0);
  const bk = [0, 0, 0, 0, 0], bn = [0, 0, 0, 0, 0];
  const cu = C.map(() => ({ b: [0, 0, 0, 0, 0], n: [0, 0, 0, 0, 0], old: [0, 0, 0, 0, 0], tot: 0 }));
  open.forEach(x => { bk[x.b] += x.v.amt; bn[x.b]++; const r = cu[x.v.c]; r.b[x.b] += x.v.amt; r.n[x.b]++; r.tot += x.v.amt; r.old[x.b] = Math.max(r.old[x.b], x.late); });
  const sales90 = INV.filter(v => v.issue > D - 90 && v.issue <= D).reduce((s, v) => s + v.amt, 0);
  return { key, D, open, tot, bk, bn, cu, dso: sales90 ? tot / sales90 * 90 : 0 };
}

/* ------------------------------------------------------------------ state */
const S = { view: 'ageing', asof: 'sep', b: null, c: null, sort: { k: 'late', dir: -1 }, sel: new Set(), csort: { k: 'bal', dir: -1 } };
let A = ageing(S.asof);

/* ------------------------------------------------------------------ tooltip + toast */
const tip = $('.dbf-ar__tip'), toast = $('.dbf-ar__toast'); let tt = 0;
function showTip(html, x, y) {
  tip.innerHTML = html; tip.classList.add('on');
  const r = root.getBoundingClientRect(), w = tip.offsetWidth, h = tip.offsetHeight;
  let l = x - r.left + 14, t = y - r.top - h - 12;
  if (l + w > r.width - 8) l = x - r.left - w - 14;
  tip.style.translate = Math.round(Math.max(8, l)) + 'px ' + Math.round(t < 8 ? y - r.top + 16 : t) + 'px';
}
const hideTip = () => tip.classList.remove('on');
function say(m) { toast.textContent = m; toast.classList.add('on'); clearTimeout(tt); tt = setTimeout(() => toast.classList.remove('on'), 2800); }

/* ------------------------------------------------------------------ number tween */
function tweenText(el, to, fmt) {
  const from = el._v == null ? to : el._v; el._v = to;
  if (RM || from === to) { el.firstChild ? el.firstChild.nodeValue = fmt(to) : el.prepend(fmt(to)); return; }
  const t0 = performance.now();
  const step = now => {
    if (!root.isConnected) return;
    const q = Math.min(1, (now - t0) / 600), e = 1 - Math.pow(1 - q, 4);
    el.firstChild.nodeValue = fmt(from + (to - from) * e);
    if (q < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* ------------------------------------------------------------------ KPIs */
const kpis = $('.dbf-ar__kpis');
kpis.innerHTML = ['Receivables', 'Past due', 'DSO', '90+ days'].map((t, i) => `<div style="--i:${i}"><dt>${t}</dt><dd>0<small></small></dd></div>`).join('');
function renderKpis() {
  const d = $$('dd', kpis), P = ageing(PREV[S.asof]), past = A.tot - A.bk[0], custs = new Set(A.open.map(x => x.v.c)).size;
  tweenText(d[0], A.tot, usd); $('small', d[0]).textContent = `${A.open.length} invoices · ${custs} customers`;
  tweenText(d[1], A.tot ? past / A.tot * 100 : 0, v => v.toFixed(1) + '%'); $('small', d[1]).textContent = k(past);
  const dd = A.dso - P.dso;
  tweenText(d[2], A.dso, v => Math.round(v) + ' days'); $('small', d[2]).innerHTML = `<b class="${dd > 0 ? 'up' : 'dn'}">${dd > 0 ? '+' : '−'}${Math.abs(dd).toFixed(1)}</b> vs ${dl(P.D)}`;
  tweenText(d[3], A.bk[4], usd); $('small', d[3]).textContent = `${A.bn[4]} invoices`;
}

/* ------------------------------------------------------------------ strip */
const strip = $('.dbf-ar__strip');
strip.innerHTML = BK.map(([n, r], i) => `<button type="button" data-b="${i}" aria-pressed="false" style="--c:var(--dbf-ar-${r});--i:${i}"><b>${n}</b><span></span></button>`).join('');
function renderStrip() {
  $$('button', strip).forEach((b, i) => {
    b.style.setProperty('--w', Math.max(A.bk[i], A.tot * 0.02));
    b.setAttribute('aria-pressed', S.b === i);
    $('span', b).innerHTML = `${k(A.bk[i])}<small>${A.tot ? Math.round(A.bk[i] / A.tot * 100) : 0}%</small>`;
    b.setAttribute('aria-label', `${BK[i][0]} days: ${usd(A.bk[i])}, ${A.bn[i]} invoices`);
  });
}
strip.addEventListener('click', e => { const b = e.target.closest('[data-b]'); if (!b) return; const i = +b.dataset.b; S.b = S.b === i ? null : i; filterChanged(); });
strip.addEventListener('keydown', e => {
  const bs = $$('button', strip), i = bs.indexOf(document.activeElement);
  const j = e.key === 'ArrowRight' ? Math.min(4, i + 1) : e.key === 'ArrowLeft' ? Math.max(0, i - 1) : -1;
  if (i >= 0 && j >= 0) { e.preventDefault(); bs[j].focus(); }
});

/* ------------------------------------------------------------------ matrix */
const mx = $('.dbf-ar__mx');
function renderMatrix() {
  const rows = A.cu.map((r, i) => ({ ...r, i })).filter(r => r.tot > 0).sort((a, b) => b.tot - a.tot);
  const max = Math.max(1, ...rows.flatMap(r => r.b));
  let q = 0;
  mx.innerHTML = `<thead><tr><th>Customer</th>${BK.map(([n, r]) => `<th style="--c:var(--dbf-ar-${r})">${n}<i></i></th>`).join('')}<th>Total</th></tr></thead><tbody>${rows.map(r =>
    `<tr><th scope="row" title="${esc(C[r.i].n)}">${esc(C[r.i].n)}</th>${r.b.map((v, b) => `<td>${v ? `<button type="button" data-c="${r.i}" data-b="${b}" aria-pressed="${S.c === r.i && (S.b == null || S.b === b)}" class="${b >= 3 && v / max > .3 ? 'hot' : ''}" style="--c:var(--dbf-ar-${BK[b][1]});--v:${Math.sqrt(v / max).toFixed(3)};--i:${q++}" aria-label="${esc(C[r.i].n)}, ${BK[b][0]}: ${usd(v)}">${k(v)}</button>` : '<span class="z">·</span>'}</td>`).join('')}<td class="t">${k(r.tot)}</td></tr>`).join('')}</tbody>
    <tfoot><tr><th>${rows.length} customers</th>${A.bk.map(v => `<td>${k(v)}</td>`).join('')}<td>${k(A.tot)}</td></tr></tfoot>`;
}
mx.addEventListener('click', e => {
  const b = e.target.closest('button[data-c]'); if (!b) return;
  const c = +b.dataset.c, bk = +b.dataset.b;
  if (S.c === c && S.b === bk) { S.c = null; S.b = null; } else { S.c = c; S.b = bk; }
  filterChanged();
});
mx.addEventListener('pointermove', e => {
  const b = e.target.closest('button[data-c]'); if (!b) { hideTip(); return; }
  const c = +b.dataset.c, bk = +b.dataset.b, r = A.cu[c];
  showTip(`<b>${esc(C[c].n)}</b><span>${BK[bk][0]} days<em>${usd(r.b[bk])}</em></span><span>Invoices<em>${r.n[bk]}</em></span><span>Oldest<em>${r.old[bk] > 0 ? r.old[bk] + ' days late' : 'not yet due'}</em></span><span>Terms<em>Net ${C[c].terms}</em></span>`, e.clientX, e.clientY);
});
mx.addEventListener('pointerleave', hideTip);

/* ------------------------------------------------------------------ invoices */
const tbody = $('.dbf-ar__inv tbody'), all = $('.dbf-ar__inv thead input');
const X = '<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M3 3l6 6M9 3l-6 6"/></svg>';
function rows() {
  const r = A.open.filter(x => (S.b == null || x.b === S.b) && (S.c == null || x.v.c === S.c));
  const { k: key, dir } = S.sort;
  const val = x => key === 'no' ? x.v.i : key === 'cust' ? C[x.v.c].n : key === 'due' ? x.v.due : key === 'amt' ? x.v.amt : x.late;
  return r.sort((a, b) => { const p = val(a), q = val(b); return (typeof p === 'string' ? p.localeCompare(q) : p - q) * dir || b.v.amt - a.v.amt; });
}
const pill = v => v.st === 'rem' ? `<span class="pill rem" title="Reminder sent ${v.stAt}">Reminded</span>` : v.st === 'dis' ? `<span class="pill dis" title="Disputed ${v.stAt}">Disputed</span>` : '<span class="pill">Open</span>';
function renderInv(flip) {
  const rs = rows(), before = new Map();
  if (flip && !RM) $$('tr[data-i]', tbody).forEach(tr => before.set(tr.dataset.i, tr.getBoundingClientRect().top));
  tbody.innerHTML = rs.map(x => `<tr data-i="${x.v.i}"><td class="ck"><input type="checkbox" aria-label="Select ${x.v.no}"${S.sel.has(x.v.i) ? ' checked' : ''}></td><td class="no">${x.v.no}</td><td class="cu">${esc(C[x.v.c].n)}</td><td class="mu">${dl(x.v.due)}</td>
    <td class="r"><span class="late" style="--c:var(--dbf-ar-${BK[x.b][1]})"><i></i>${x.late > 0 ? x.late : x.late === 0 ? 'due today' : `in ${-x.late}d`}</span></td><td class="r"><b>${usd(x.v.amt)}</b></td><td>${pill(x.v)}</td></tr>`).join('') || '<tr class="empty"><td colspan="7">No open invoices match these filters.</td></tr>';
  if (before.size) $$('tr[data-i]', tbody).forEach(tr => { const b = before.get(tr.dataset.i); if (b == null) return; const dy = b - tr.getBoundingClientRect().top; if (Math.abs(dy) > 1) tr.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 480, easing: SPRING }); });
  const sum = rs.reduce((s, x) => s + x.v.amt, 0);
  const chips = [];
  if (S.c != null) chips.push(`<button type="button" data-x="c">${esc(C[S.c].n)}${X}</button>`);
  if (S.b != null) chips.push(`<button type="button" data-x="b" style="--c:var(--dbf-ar-${BK[S.b][1]})"><i></i>${BK[S.b][0]} days${X}</button>`);
  $('.dbf-ar__filters').innerHTML = `${chips.length ? '' : 'All open invoices'}${chips.join('')}<span>${rs.length} · ${usd(sum)}</span>`;
  $$('.dbf-ar__inv th[data-k]').forEach(th => th.setAttribute('aria-sort', th.dataset.k === S.sort.k ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'));
  syncSel();
}
function syncSel() {
  const vis = $$('tr[data-i]', tbody).map(tr => +tr.dataset.i), n = vis.filter(i => S.sel.has(i)).length;
  all.checked = n > 0 && n === vis.length; all.indeterminate = n > 0 && n < vis.length;
  const amt = [...S.sel].reduce((s, i) => s + INV[i].amt, 0);
  $('.dbf-ar__selc').textContent = `${S.sel.size} selected · ${usd(amt)}`;
}
$('.dbf-ar__filters').addEventListener('click', e => { const b = e.target.closest('[data-x]'); if (!b) return; S[b.dataset.x] = null; filterChanged(); });
tbody.addEventListener('change', e => { const tr = e.target.closest('tr[data-i]'); if (!tr) return; const i = +tr.dataset.i; e.target.checked ? S.sel.add(i) : S.sel.delete(i); syncSel(); });
tbody.addEventListener('click', e => { if (e.target.closest('input')) return; const tr = e.target.closest('tr[data-i]'); if (!tr) return; const cb = $('input', tr); cb.checked = !cb.checked; cb.dispatchEvent(new Event('change', { bubbles: true })); });
all.addEventListener('change', () => { $$('tr[data-i]', tbody).forEach(tr => { const i = +tr.dataset.i; all.checked ? S.sel.add(i) : S.sel.delete(i); $('input', tr).checked = all.checked; }); syncSel(); });
