@property --dbf-treasury-turn { syntax: "<angle>"; inherits: false; initial-value: 0deg; }

.dbf-treasury {
  /* re-theme with these four */
  --dbf-treasury-bg: oklch(0.18 0.012 70);
  --dbf-treasury-ink: oklch(0.93 0.025 85);
  --dbf-treasury-brass: oklch(0.8 0.11 82);
  --dbf-treasury-neg: oklch(0.68 0.15 28);
  /* derived */
  --dbf-treasury-pos: oklch(from var(--dbf-treasury-brass) calc(l - 0.04) calc(c * 0.9) 150);
  --dbf-treasury-card: color-mix(in oklch, var(--dbf-treasury-bg), var(--dbf-treasury-ink) 5%);
  --dbf-treasury-raise: color-mix(in oklch, var(--dbf-treasury-bg), var(--dbf-treasury-ink) 10%);
  --dbf-treasury-line: color-mix(in oklch, var(--dbf-treasury-ink) 11%, transparent);
  --dbf-treasury-soft: color-mix(in oklch, var(--dbf-treasury-ink) 6%, transparent);
  --dbf-treasury-mute: color-mix(in oklch, var(--dbf-treasury-ink) 62%, var(--dbf-treasury-bg));
  --dbf-treasury-faint: color-mix(in oklch, var(--dbf-treasury-ink) 40%, var(--dbf-treasury-bg));
  --dbf-treasury-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-treasury-serif: ui-serif, "New York", Georgia, serif;
  --dbf-treasury-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-treasury-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-treasury-spring: linear(0, 0.009, 0.035 2.1%, 0.141 4.4%, 0.723 12.9%, 0.938 16.7%, 1.017 19.4%, 1.067, 1.077 24.3%, 1.071 26.3%, 1.042 30.4%, 0.996 39.3%, 0.991 42.5%, 1.001 54%, 1);
  width: 100%;
  height: var(--dbf-treasury-h, 680px);
  container-type: inline-size; container-name: dbf-treasury;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbf-treasury-bg);
  color: var(--dbf-treasury-ink);
  font: 13px/1.45 var(--dbf-treasury-sans);
  accent-color: var(--dbf-treasury-brass);
  color-scheme: dark;
  box-shadow: inset 0 0 0 1px var(--dbf-treasury-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ul, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbf-treasury-brass); outline-offset: 2px; border-radius: 6px; }
}
.dbf-treasury__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-treasury__shell { height: 100%; display: grid; grid-template-columns: 190px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dbf-treasury__side { display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; border-right: 1px solid var(--dbf-treasury-line); }
.dbf-treasury__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 22px;
  & svg { width: 30px; height: 30px; flex: none; fill: none; stroke: var(--dbf-treasury-brass); stroke-width: 1.3; }
  & b { display: block; font: 600 15px/1.1 var(--dbf-treasury-serif); letter-spacing: -.01em; }
  & small { display: block; font-size: 10.5px; letter-spacing: .14em; text-transform: uppercase; color: var(--dbf-treasury-mute); }
}
.dbf-treasury__nav { display: grid; gap: 2px; }
.dbf-treasury__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; color: var(--dbf-treasury-mute); font-weight: 550; text-align: left; transition: background-color .2s, color .2s;
  &:hover { color: var(--dbf-treasury-ink); background: var(--dbf-treasury-soft); }
  &[aria-current="page"] { color: var(--dbf-treasury-ink); background: var(--dbf-treasury-raise); box-shadow: inset 2px 0 0 var(--dbf-treasury-brass); }
  &[aria-current="page"] .dbf-treasury__ic { color: var(--dbf-treasury-brass); }
}
.dbf-treasury__foot { margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbf-treasury-line); font-size: 11.5px; color: var(--dbf-treasury-mute); text-wrap: pretty; & b { display: block; color: var(--dbf-treasury-ink); font-weight: 650; } }

/* ---------------------------------------------------------------- main */
.dbf-treasury__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 16px 18px; }
.dbf-treasury__head {
  display: flex; align-items: flex-end; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap;
  & h2 { font: 500 clamp(20px, 2.4cqi, 27px)/1.1 var(--dbf-treasury-serif); letter-spacing: -.015em; text-wrap: balance; }
}
.dbf-treasury__eyebrow { font: 500 11px var(--dbf-treasury-mono); color: var(--dbf-treasury-mute); margin-bottom: 3px; }
.dbf-treasury__ccy {
  display: inline-flex; padding: 3px; gap: 2px; border-radius: 11px; box-shadow: inset 0 0 0 1px var(--dbf-treasury-line);
  & button { padding: 5px 11px; border-radius: 8px; font: 600 12px var(--dbf-treasury-mono); letter-spacing: .04em; color: var(--dbf-treasury-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dbf-treasury-ink); }
  & button[aria-checked="true"] { background: var(--dbf-treasury-brass); color: var(--dbf-treasury-bg); }
}
.dbf-treasury__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  transition: opacity .35s var(--dbf-treasury-out), translate .5s var(--dbf-treasury-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-treasury__pv {
  grid-template-columns: 286px minmax(0, 1fr);
  grid-template-rows: auto minmax(0, .85fr) minmax(0, 1.15fr);
  grid-template-areas: "hero hero" "mix ent" "mix acct";
}
.dbf-treasury__panel {
  min-width: 0; min-height: 0; display: flex; flex-direction: column; position: relative;
  background: var(--dbf-treasury-card); border-radius: 14px; box-shadow: inset 0 0 0 1px var(--dbf-treasury-line);
  animation: dbf-treasury-rise .7s var(--dbf-treasury-out) both; animation-delay: calc(var(--i, 0) * 80ms + 120ms);
}
.dbf-treasury__ph {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 11px 14px 6px; min-height: 40px; flex-wrap: wrap;
  & h3 { font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dbf-treasury-mute); }
}
.dbf-treasury__unit { font: 11px var(--dbf-treasury-mono); color: var(--dbf-treasury-faint); }

/* ---------------------------------------------------------------- odometer */
.dbf-treasury__odo {
  display: inline-flex; align-items: flex-start; line-height: 1.25; height: 1.25em; overflow: hidden; font-variant-numeric: tabular-nums; white-space: nowrap; vertical-align: middle;
  & .d { display: inline-block; width: 1ch; height: 1.25em; overflow: hidden; }
  & .col { display: flex; flex-direction: column; transform: translateY(calc(var(--v) * -10%)); transition: transform 1s var(--dbf-treasury-spring); transition-delay: calc(var(--i) * 32ms); }
  & .col i { font-style: normal; height: 1.25em; line-height: 1.25; display: block; text-align: center; }
  & .s { display: inline-block; }
  & .s.sep { opacity: .55; }
}

/* ---------------------------------------------------------------- hero */
.dbf-treasury__hero {
  grid-area: hero; position: relative; overflow: hidden; display: flex; align-items: flex-end; gap: 14px 34px; padding: 14px 20px 14px; border-radius: 16px; flex-wrap: wrap;
  background: linear-gradient(120deg, color-mix(in oklch, var(--dbf-treasury-brass) 14%, var(--dbf-treasury-card)), var(--dbf-treasury-card) 60%);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--dbf-treasury-brass) 30%, transparent);
  animation: dbf-treasury-rise .7s var(--dbf-treasury-out) both;
}
.dbf-treasury__rosette {
  position: absolute; right: -40px; top: 50%; width: 300px; height: 300px; translate: 0 -50%; pointer-events: none;
  fill: none; stroke: var(--dbf-treasury-brass); stroke-width: .35; opacity: .28;
  rotate: var(--dbf-treasury-turn); animation: dbf-treasury-spin 160s linear infinite;
  .dbf-treasury.off & { animation-play-state: paused; }
}
.dbf-treasury__big {
  position: relative;
  & p { font-size: 11px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--dbf-treasury-brass); margin-bottom: 8px; }
  & .dbf-treasury__odo { font: 300 clamp(30px, 4.2cqi, 44px) var(--dbf-treasury-sans); letter-spacing: -.03em; font-variant-numeric: tabular-nums lining-nums; }
}
.dbf-treasury__stats {
  position: relative; display: flex; gap: 12px 26px; flex-wrap: wrap; padding-bottom: 2px;
  & div { display: grid; gap: 4px; }
  & dt { font-size: 11px; color: var(--dbf-treasury-mute); }
  & div { gap: 2px; }
  & dd { font-size: 17px; font-weight: 600; letter-spacing: -.01em; line-height: 1.2; }
  & dd small { display: block; font-size: 11px; font-weight: 500; color: var(--dbf-treasury-faint); }
}

/* ---------------------------------------------------------------- donut + legend */
.dbf-treasury__mix { grid-area: mix; --i: 1; }
.dbf-treasury__donut {
  position: relative; width: 170px; aspect-ratio: 1; margin: 2px auto 8px; flex: none;
  & svg { width: 100%; height: 100%; rotate: -90deg; overflow: visible; }
  & circle { fill: none; stroke-width: 15; transition: stroke-dasharray 1.1s var(--dbf-treasury-out), stroke-dashoffset 1.1s var(--dbf-treasury-out), stroke-width .3s var(--dbf-treasury-out), opacity .25s; cursor: pointer; }
  & circle.track { stroke: var(--dbf-treasury-soft); cursor: default; }
  & circle.on { stroke-width: 19; }
  &:has(circle.on) circle:not(.on, .track) { opacity: .35; }
}
.dbf-treasury__dc {
  position: absolute; inset: 0; display: grid; place-content: center; text-align: center; pointer-events: none;
  & small { font: 600 10.5px var(--dbf-treasury-mono); letter-spacing: .08em; color: var(--dbf-treasury-mute); }
  & b { font: 500 17px var(--dbf-treasury-serif); font-variant-numeric: tabular-nums; }
}
.dbf-treasury__legend {
  list-style: none; padding: 0 8px 10px; overflow: auto; scrollbar-width: thin; flex: 1; min-height: 0;
  & button { width: 100%; display: grid; grid-template-columns: 10px 38px minmax(0, 1fr) auto; gap: 8px; align-items: center; padding: 6px 8px; border-radius: 8px; text-align: left; font-variant-numeric: tabular-nums; transition: background-color .15s; }
  & button:hover, & button[aria-pressed="true"] { background: var(--dbf-treasury-soft); }
  & button[aria-pressed="true"] { box-shadow: inset 0 0 0 1px var(--c); }
  & i { width: 10px; height: 10px; border-radius: 3px; background: var(--c); }
  & .c { font: 600 12px var(--dbf-treasury-mono); }
  & .l { color: var(--dbf-treasury-mute); font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .p { font-weight: 650; }
}

/* ---------------------------------------------------------------- entity bars */
.dbf-treasury__ent { grid-area: ent; --i: 2; }
.dbf-treasury__bars {
  flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; padding: 0 14px 10px; display: grid; gap: 5px; align-content: start;
  & .row { display: grid; grid-template-columns: 150px minmax(0, 1fr) 96px; gap: 12px; align-items: center; border-radius: 8px; padding: 1px 0; cursor: pointer; }
  & .row:hover .n, & .row.on .n { color: var(--dbf-treasury-brass); }
  & .n { font-weight: 600; font-size: 12.5px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; transition: color .15s; }
  & .n small { font: 10.5px var(--dbf-treasury-mono); color: var(--dbf-treasury-faint); margin-left: 4px; }
  & .b { display: flex; height: 14px; gap: 2px; width: calc(var(--w) * 100%); transform-origin: 0 50%; animation: dbf-treasury-growx 1s var(--dbf-treasury-out) both; animation-delay: calc(var(--i) * 70ms + 200ms); transition: width .8s var(--dbf-treasury-out); }
  & .b span { flex: var(--f) 1 0; min-width: 2px; background: var(--c); border-radius: 2px; transition: opacity .2s; }
  & .v { text-align: right; font-variant-numeric: tabular-nums; font-size: 12.5px; font-weight: 600; }
}
.dbf-treasury__pv:has(.dbf-treasury__legend [aria-pressed="true"]) .dbf-treasury__bars .b span:not(.hit) { opacity: .22; }

/* ---------------------------------------------------------------- accounts */
.dbf-treasury__acct { grid-area: acct; --i: 3; }
.dbf-treasury__chips {
  display: flex; gap: 6px;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 3px 6px 3px 9px; border-radius: 7px; font-size: 11.5px; font-weight: 600; background: var(--dbf-treasury-soft); box-shadow: inset 0 0 0 1px var(--dbf-treasury-line); }
  & button:hover { box-shadow: inset 0 0 0 1px var(--dbf-treasury-brass); }
  & svg { width: 11px; height: 11px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }
}
.dbf-treasury__scroll { flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbf-treasury-ink) 20%, transparent) transparent; }
.dbf-treasury__tbl {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbf-treasury-card); text-align: left; padding: 0 12px; height: 30px; font-size: 10.5px; font-weight: 650; letter-spacing: .08em; text-transform: uppercase; color: var(--dbf-treasury-faint); border-bottom: 1px solid var(--dbf-treasury-line); white-space: nowrap; }
  & .r { text-align: right; }
  & td { padding: 0 12px; height: 38px; border-bottom: 1px solid var(--dbf-treasury-soft); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & tbody tr { transition: background-color .15s; animation: dbf-treasury-fade .45s ease-out both; animation-delay: calc(var(--i) * 25ms); }
  & tbody tr:hover { background: var(--dbf-treasury-soft); }
  & .bk b { font-weight: 600; }
