@property --dbf-fraud-a { syntax: "<angle>"; inherits: true; initial-value: 0deg; }

.dbf-fraud {
  /* re-theme with these four */
  --dbf-fraud-bg: oklch(0.175 0.008 260);
  --dbf-fraud-ink: oklch(0.94 0.008 260);
  --dbf-fraud-hot: oklch(0.64 0.21 22);
  --dbf-fraud-safe: oklch(0.76 0.12 168);
  /* derived */
  --dbf-fraud-warm: oklch(from var(--dbf-fraud-hot) calc(l + 0.17) calc(c * 0.7) 75);
  --dbf-fraud-card: color-mix(in oklch, var(--dbf-fraud-bg), var(--dbf-fraud-ink) 4.5%);
  --dbf-fraud-raise: color-mix(in oklch, var(--dbf-fraud-bg), var(--dbf-fraud-ink) 9%);
  --dbf-fraud-line: color-mix(in oklch, var(--dbf-fraud-ink) 10%, transparent);
  --dbf-fraud-soft: color-mix(in oklch, var(--dbf-fraud-ink) 6%, transparent);
  --dbf-fraud-mute: color-mix(in oklch, var(--dbf-fraud-ink) 62%, var(--dbf-fraud-bg));
  --dbf-fraud-faint: color-mix(in oklch, var(--dbf-fraud-ink) 40%, var(--dbf-fraud-bg));
  --dbf-fraud-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-fraud-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-fraud-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-fraud-snap: cubic-bezier(.3, 1.4, .5, 1);
  width: 100%;
  height: var(--dbf-fraud-h, 680px);
  container-type: inline-size; container-name: dbf-fraud;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbf-fraud-bg);
  color: var(--dbf-fraud-ink);
  font: 13px/1.45 var(--dbf-fraud-sans);
  accent-color: var(--dbf-fraud-hot);
  color-scheme: dark;
  box-shadow: inset 0 0 0 1px var(--dbf-fraud-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, h4, p, dl, dd, ul, ol, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbf-fraud-ink); outline-offset: 2px; border-radius: 6px; }
  & kbd { display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px; border-radius: 5px; font: 600 10.5px var(--dbf-fraud-mono); background: var(--dbf-fraud-soft); box-shadow: inset 0 -1px 0 var(--dbf-fraud-line), inset 0 0 0 1px var(--dbf-fraud-line); color: var(--dbf-fraud-ink); }
}
.dbf-fraud__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-fraud__shell { height: 100%; display: grid; grid-template-columns: 180px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dbf-fraud__side { display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; border-right: 1px solid var(--dbf-fraud-line); background: color-mix(in oklch, var(--dbf-fraud-bg), black 25%); }
.dbf-fraud__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 22px;
  & svg { width: 28px; height: 28px; flex: none; fill: color-mix(in oklch, var(--dbf-fraud-hot) 18%, transparent); stroke: var(--dbf-fraud-hot); stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 14.5px; font-weight: 720; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbf-fraud-mute); }
}
.dbf-fraud__nav { display: grid; gap: 2px; }
.dbf-fraud__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; color: var(--dbf-fraud-mute); font-weight: 550; text-align: left; transition: background-color .2s, color .2s;
  &:hover { color: var(--dbf-fraud-ink); background: var(--dbf-fraud-soft); }
  &[aria-current="page"] { color: var(--dbf-fraud-ink); background: var(--dbf-fraud-raise); }
  & em { margin-left: auto; font: 600 11px var(--dbf-fraud-mono); font-style: normal; padding: 1px 6px; border-radius: 6px; background: var(--dbf-fraud-soft); color: var(--dbf-fraud-mute); }
  &[data-view="queue"] em { background: color-mix(in oklch, var(--dbf-fraud-hot) 22%, transparent); color: var(--dbf-fraud-ink); }
  & em.bump { animation: dbf-fraud-bump .5s var(--dbf-fraud-snap); }
}
.dbf-fraud__foot {
  margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbf-fraud-line); font-size: 11.5px; color: var(--dbf-fraud-mute); display: grid; gap: 10px;
  & b { display: block; color: var(--dbf-fraud-ink); font-weight: 650; }
  & span { font-variant-numeric: tabular-nums; }
}
.dbf-fraud__help-btn { display: inline-flex; align-items: center; gap: 6px; font-size: 11.5px; color: var(--dbf-fraud-mute); &:hover { color: var(--dbf-fraud-ink); } }

/* ---------------------------------------------------------------- views */
.dbf-fraud__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; }
.dbf-fraud__view {
  flex: 1; min-height: 0; display: grid;
  transition: opacity .35s var(--dbf-fraud-out), translate .5s var(--dbf-fraud-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-fraud__qv { grid-template-columns: 292px minmax(0, 1fr); }

/* ---------------------------------------------------------------- queue */
.dbf-fraud__queue { display: flex; flex-direction: column; min-height: 0; border-right: 1px solid var(--dbf-fraud-line); }
.dbf-fraud__qh { display: grid; gap: 8px; padding: 16px 14px 10px; & h2 { font-size: 19px; font-weight: 720; letter-spacing: -.03em; } }
.dbf-fraud__sev {
  display: flex; padding: 2px; border-radius: 9px; background: var(--dbf-fraud-soft);
  & button { flex: 1; padding: 4px 6px; border-radius: 7px; font-size: 11.5px; font-weight: 600; color: var(--dbf-fraud-mute); transition: background-color .2s, color .2s; }
  & button:hover { color: var(--dbf-fraud-ink); }
  & button[aria-checked="true"] { background: var(--dbf-fraud-raise); color: var(--dbf-fraud-ink); }
}
.dbf-fraud__list {
  list-style: none; flex: 1; min-height: 0; overflow: auto; scrollbar-width: thin; scrollbar-color: color-mix(in oklch, var(--dbf-fraud-ink) 18%, transparent) transparent; padding: 0 8px 12px; display: grid; align-content: start; gap: 3px;
  & li {
    --sc: var(--dbf-fraud-faint);
    position: relative; display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 10px 9px 14px; border-radius: 10px; cursor: pointer;
    transition: background-color .15s, box-shadow .2s;
    animation: dbf-fraud-in .45s var(--dbf-fraud-out) both; animation-delay: calc(var(--i) * 35ms);
  }
  & li.high { --sc: var(--dbf-fraud-hot); } & li.med { --sc: var(--dbf-fraud-warm); } & li.low { --sc: var(--dbf-fraud-safe); }
  & li::before { content: ""; position: absolute; left: 4px; top: 10px; bottom: 10px; width: 3px; border-radius: 2px; background: var(--sc); }
  & li:hover { background: var(--dbf-fraud-soft); }
  & li[aria-selected="true"] { background: var(--dbf-fraud-raise); box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); }
  & li:focus-visible { outline-offset: -2px; }
  & .who { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .amt { font: 600 12.5px var(--dbf-fraud-mono); text-align: right; font-variant-numeric: tabular-nums; }
  & .mer { font-size: 11.5px; color: var(--dbf-fraud-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .meta { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; font-size: 11px; color: var(--dbf-fraud-faint); font-variant-numeric: tabular-nums; }
  & .score { font: 700 11px var(--dbf-fraud-mono); color: var(--sc); }
  & .sla { margin-left: auto; font-family: var(--dbf-fraud-mono); }
  & .sla.late { color: var(--dbf-fraud-hot); animation: dbf-fraud-blink 1.2s steps(2) infinite; }
  & .empty { cursor: default; display: block; text-align: center; padding: 40px 10px; color: var(--dbf-fraud-mute); }
  & .empty::before { display: none; }
}
.dbf-fraud.off .dbf-fraud__list .sla.late { animation-play-state: paused; }

/* ---------------------------------------------------------------- case */
.dbf-fraud__case {
  min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; position: relative;
  & > .body { min-height: 0; overflow: auto; scrollbar-width: thin; padding: 6px 18px 14px; display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "score time" "sig geo"; gap: 12px; align-content: start; }
  &.swap > * { animation: dbf-fraud-swap .45s var(--dbf-fraud-out) both; }
  &.swap > .body { animation-delay: 60ms; }
}
.dbf-fraud__ch {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 4px 16px; align-items: end; padding: 16px 18px 10px;
  & .k { font: 500 11px var(--dbf-fraud-mono); color: var(--dbf-fraud-mute); display: flex; gap: 10px; flex-wrap: wrap; }
  & .k b { color: var(--sc); font-weight: 700; letter-spacing: .06em; text-transform: uppercase; }
  & h3 { font-size: clamp(18px, 2.1cqi, 23px); font-weight: 720; letter-spacing: -.03em; line-height: 1.15; text-wrap: balance; }
  & h3 span { color: var(--dbf-fraud-mute); font-weight: 500; }
  & .big { font: 600 clamp(20px, 2.4cqi, 26px) var(--dbf-fraud-mono); letter-spacing: -.03em; text-align: right; font-variant-numeric: tabular-nums; }
  & .big small { display: block; font: 500 11px var(--dbf-fraud-sans); letter-spacing: 0; color: var(--dbf-fraud-mute); }
}
.dbf-fraud__card { background: var(--dbf-fraud-card); border-radius: 14px; box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); padding: 12px 14px; min-width: 0; }
.dbf-fraud__card h4 { font-size: 10.5px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: var(--dbf-fraud-faint); margin-bottom: 8px; display: flex; justify-content: space-between; gap: 8px; }
.dbf-fraud__card h4 span { letter-spacing: 0; text-transform: none; font-weight: 500; font-family: var(--dbf-fraud-mono); }

/* score dial: 270 degree conic gauge driven by an animated @property angle */
.dbf-fraud__score { grid-area: score; display: grid; grid-template-columns: 124px minmax(0, 1fr); gap: 14px; align-items: center; }
.dbf-fraud__dial {
  --c: var(--dbf-fraud-hot);
  position: relative; width: 124px; aspect-ratio: 1; display: grid; place-items: center;
  transition: --dbf-fraud-a 1.1s var(--dbf-fraud-out);
  &::before {
    content: ""; position: absolute; inset: 0; border-radius: 50%;
    background: conic-gradient(from 225deg, var(--c) 0 var(--dbf-fraud-a), var(--dbf-fraud-soft) var(--dbf-fraud-a) 270deg, transparent 270deg);
    mask: radial-gradient(farthest-side, transparent calc(100% - 10px), black calc(100% - 9px));
  }
  &::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: conic-gradient(from 225deg, transparent 0 calc(var(--th) * 270deg - 1deg), var(--dbf-fraud-ink) 0 calc(var(--th) * 270deg + 1deg), transparent 0); mask: radial-gradient(farthest-side, transparent calc(100% - 14px), black calc(100% - 13px)); opacity: .7; }
  &.med { --c: var(--dbf-fraud-warm); } &.low { --c: var(--dbf-fraud-safe); }
  & b { font: 650 34px/1 var(--dbf-fraud-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; }
  & small { position: absolute; bottom: 14px; font-size: 10px; letter-spacing: .1em; text-transform: uppercase; color: var(--dbf-fraud-mute); }
}
.dbf-fraud__facts {
  display: grid; gap: 6px; font-size: 12px; min-width: 0;
  & div { display: grid; gap: 0; border-bottom: 1px solid var(--dbf-fraud-soft); padding-bottom: 5px; min-width: 0; }
  & div:last-child { border-bottom: 0; }
  & dt { font-size: 10.5px; color: var(--dbf-fraud-faint); letter-spacing: .02em; }
  & dd { font-weight: 600; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

/* signal contributions: additive waterfall from base rate to score */
.dbf-fraud__sig { grid-area: sig; }
.dbf-fraud__wf {
  list-style: none; display: grid; gap: 5px;
  & li { display: grid; grid-template-columns: minmax(0, 1fr) 40px; gap: 4px 10px; align-items: center; font-size: 12px; animation: dbf-fraud-in .4s var(--dbf-fraud-out) both; animation-delay: calc(var(--i) * 45ms + 150ms); }
  & .lb { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: color-mix(in oklch, var(--dbf-fraud-ink) 85%, var(--dbf-fraud-bg)); }
  & .pt { font: 600 11.5px var(--dbf-fraud-mono); text-align: right; color: var(--dbf-fraud-hot); }
  & .pt.neg { color: var(--dbf-fraud-safe); }
  & .tr { grid-column: 1 / -1; position: relative; height: 6px; border-radius: 3px; background: var(--dbf-fraud-soft); }
  & .tr i { position: absolute; top: 0; bottom: 0; left: calc(var(--a) * 1%); width: calc(var(--w) * 1%); border-radius: 3px; background: var(--dbf-fraud-hot); transform-origin: 0 50%; animation: dbf-fraud-growx .6s var(--dbf-fraud-out) both; animation-delay: calc(var(--i) * 45ms + 250ms); }
  & .tr i.neg { background: var(--dbf-fraud-safe); transform-origin: 100% 50%; }
  & .tr i.base { background: var(--dbf-fraud-faint); }
  & li.tot { border-top: 1px solid var(--dbf-fraud-line); padding-top: 6px; font-weight: 700; }
  & li.tot .pt { color: var(--dbf-fraud-ink); }
}

/* 24h timeline */
.dbf-fraud__time { grid-area: time; }
.dbf-fraud__tl {
  width: 100%; height: 96px; display: block; overflow: visible;
  & .ax { stroke: var(--dbf-fraud-line); }
  & text { font: 10px var(--dbf-fraud-mono); fill: var(--dbf-fraud-faint); }
  & .tx { fill: color-mix(in oklch, var(--dbf-fraud-ink) 55%, transparent); transition: r .2s var(--dbf-fraud-snap); cursor: pointer; }
  & .tx.dec { fill: none; stroke: var(--dbf-fraud-hot); stroke-width: 1.5; }
  & .tx.cur { fill: var(--dbf-fraud-hot); }
  & .ring { fill: none; stroke: var(--dbf-fraud-hot); stroke-width: 1.5; transform-box: fill-box; transform-origin: center; animation: dbf-fraud-ping 1.8s var(--dbf-fraud-out) infinite; }
  & .stem { stroke: color-mix(in oklch, var(--dbf-fraud-ink) 18%, transparent); }
  & .tx:hover { r: 7; }
}
.dbf-fraud.off .dbf-fraud__tl .ring { animation-play-state: paused; }

/* geo */
.dbf-fraud__geo { grid-area: geo; display: grid; grid-template-rows: auto auto minmax(0, 1fr); }
.dbf-fraud__map {
  width: 100%; height: 110px; display: block; overflow: visible;
  & .dot { fill: color-mix(in oklch, var(--dbf-fraud-ink) 16%, transparent); }
  & .arc { fill: none; stroke: var(--dbf-fraud-hot); stroke-width: 1.6; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dbf-fraud-draw 1.2s var(--dbf-fraud-out) .3s forwards; }
  & .arc.ok { stroke: var(--dbf-fraud-safe); }
  & .pin { fill: var(--dbf-fraud-ink); }
  & .pin.far { fill: var(--dbf-fraud-hot); }
  & .pin.far.ok { fill: var(--dbf-fraud-safe); }
  & text { font: 600 10.5px var(--dbf-fraud-sans); fill: var(--dbf-fraud-ink); }
  & text.s { font-weight: 400; fill: var(--dbf-fraud-mute); }
}
.dbf-fraud__gnote { font-size: 12px; color: var(--dbf-fraud-mute); text-wrap: pretty; & b { color: var(--dbf-fraud-ink); } }

/* action bar */
.dbf-fraud__acts {
  display: flex; align-items: center; gap: 8px; padding: 10px 18px 14px; border-top: 1px solid var(--dbf-fraud-line); flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 8px; padding: 8px 12px; border-radius: 10px; font-size: 12.5px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); transition: background-color .15s, box-shadow .15s, transform .15s var(--dbf-fraud-snap); }
  & button:active { transform: scale(.96); }
  & button:hover { background: var(--dbf-fraud-soft); }
  & .ap:hover { box-shadow: inset 0 0 0 1px var(--dbf-fraud-safe); }
  & .de { background: var(--dbf-fraud-hot); color: white; box-shadow: none; }
  & .de:hover { background: color-mix(in oklch, var(--dbf-fraud-hot), white 10%); }
  & .de kbd { background: oklch(1 0 0 / .2); color: white; box-shadow: none; }
  & .note { margin-left: auto; font-size: 11.5px; color: var(--dbf-fraud-faint); }
}

/* ---------------------------------------------------------------- decided + rules */
.dbf-fraud__dv, .dbf-fraud__rv { grid-template-rows: auto minmax(0, 1fr); padding: 16px 18px 14px; gap: 12px; }
.dbf-fraud__vh { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; flex-wrap: wrap; & h2 { font-size: 19px; font-weight: 720; letter-spacing: -.03em; } & span { font-size: 12px; color: var(--dbf-fraud-mute); font-variant-numeric: tabular-nums; } }
.dbf-fraud__scroll { min-height: 0; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dbf-fraud-card); box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); }
.dbf-fraud__dt {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; background: var(--dbf-fraud-card); text-align: left; padding: 0 12px; height: 32px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbf-fraud-faint); border-bottom: 1px solid var(--dbf-fraud-line); }
  & td { padding: 0 12px; height: 42px; border-bottom: 1px solid var(--dbf-fraud-soft); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & .r { text-align: right; }
  & .mono { font-family: var(--dbf-fraud-mono); font-size: 12px; }
  & .mu { color: var(--dbf-fraud-mute); }
  & .dz { display: inline-flex; align-items: center; gap: 6px; font-weight: 650; }
  & .dz i { width: 8px; height: 8px; border-radius: 50%; }
  & .dz.a i { background: var(--dbf-fraud-safe); } & .dz.d i { background: var(--dbf-fraud-hot); } & .dz.e i { background: var(--dbf-fraud-warm); }
  & button { font-size: 11.5px; font-weight: 650; padding: 4px 9px; border-radius: 7px; box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); }
  & button:hover { background: var(--dbf-fraud-soft); }
  & tbody tr { animation: dbf-fraud-in .4s var(--dbf-fraud-out) both; animation-delay: calc(var(--i) * 30ms); }
  & .empty td { text-align: center; color: var(--dbf-fraud-mute); height: 90px; }
}
.dbf-fraud__rules {
  list-style: none; padding: 6px 14px 12px;
  & li { display: grid; grid-template-columns: 34px minmax(0, 1.3fr) minmax(0, 1fr) 70px 64px; gap: 14px; align-items: center; padding: 11px 0; border-bottom: 1px solid var(--dbf-fraud-soft); }
  & li:last-child { border-bottom: 0; }
  & li.off .nm, & li.off .bars { opacity: .4; }
  & .nm b { display: block; font-weight: 650; }
  & .nm small { font: 11px var(--dbf-fraud-mono); color: var(--dbf-fraud-faint); }
  & .bars { display: grid; gap: 4px; }
  & .bars span { height: 6px; border-radius: 3px; background: var(--dbf-fraud-soft); position: relative; overflow: hidden; }
  & .bars i { position: absolute; inset: 0 auto 0 0; width: calc(var(--w) * 100%); border-radius: inherit; background: var(--dbf-fraud-mute); transform-origin: 0 50%; animation: dbf-fraud-growx .8s var(--dbf-fraud-out) both; animation-delay: calc(var(--i) * 50ms + 100ms); }
  & .bars .p i { background: var(--dbf-fraud-hot); }
  & .v { text-align: right; font: 600 12px var(--dbf-fraud-mono); font-variant-numeric: tabular-nums; }
  & .v small { display: block; font: 400 10.5px var(--dbf-fraud-sans); color: var(--dbf-fraud-faint); }
}
.dbf-fraud__sw {
  width: 30px; height: 18px; border-radius: 9px; position: relative; background: color-mix(in oklch, var(--dbf-fraud-ink) 20%, transparent); transition: background-color .25s;
  &::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: var(--dbf-fraud-ink); transition: translate .35s var(--dbf-fraud-snap); }
  &[aria-checked="true"] { background: var(--dbf-fraud-hot); }
  &[aria-checked="true"]::after { translate: 12px 0; }
}

/* ---------------------------------------------------------------- overlays */
.dbf-fraud__toast {
  position: absolute; right: 18px; top: 14px; z-index: 40; translate: 0 -12px; opacity: 0; pointer-events: none; display: flex; align-items: center; gap: 12px;
  padding: 9px 10px 9px 14px; border-radius: 12px; background: var(--dbf-fraud-ink); color: var(--dbf-fraud-bg); font-size: 12.5px; font-weight: 600; white-space: nowrap;
  box-shadow: 0 16px 34px -12px black; transition: opacity .25s, translate .45s var(--dbf-fraud-snap);
  & button { padding: 4px 9px; border-radius: 7px; background: color-mix(in oklch, var(--dbf-fraud-bg) 12%, transparent); font-weight: 700; }
  & kbd { background: color-mix(in oklch, var(--dbf-fraud-bg) 15%, transparent); color: var(--dbf-fraud-bg); box-shadow: none; }
  &.on { opacity: 1; translate: 0 0; pointer-events: auto; }
}
.dbf-fraud__help {
  position: absolute; inset: 0; z-index: 50; display: grid; place-items: center; background: color-mix(in oklch, var(--dbf-fraud-bg) 60%, transparent); backdrop-filter: blur(6px);
  opacity: 1; transition: opacity .25s, display .25s allow-discrete;
  @starting-style { opacity: 0; }
  &[hidden] { display: none; opacity: 0; }
}
.dbf-fraud__hp {
  width: min(340px, calc(100% - 32px)); padding: 18px; border-radius: 16px; background: var(--dbf-fraud-raise); box-shadow: inset 0 0 0 1px var(--dbf-fraud-line), 0 30px 60px -20px black;
  scale: 1; transition: scale .35s var(--dbf-fraud-snap);
  @starting-style { scale: .94; }
  & h3 { font-size: 15px; font-weight: 700; margin-bottom: 10px; }
  & dl { display: grid; gap: 8px; }
  & dl div { display: grid; grid-template-columns: 70px 1fr; gap: 10px; align-items: center; font-size: 12.5px; }
  & dt { display: flex; gap: 4px; }
  & dd { color: var(--dbf-fraud-mute); }
  & .dbf-fraud__close { margin-top: 14px; width: 100%; padding: 8px; border-radius: 9px; font-weight: 650; box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); &:hover { background: var(--dbf-fraud-soft); } }
}
.dbf-fraud__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; padding: 8px 10px; border-radius: 9px; font-size: 12px; line-height: 1.45;
  background: color-mix(in oklch, var(--dbf-fraud-bg), white 13%); box-shadow: 0 0 0 1px var(--dbf-fraud-line), 0 12px 28px -12px black;
  opacity: 0; transition: opacity .14s; font-variant-numeric: tabular-nums;
  & b { display: block; } & span { color: var(--dbf-fraud-mute); }
  &.on { opacity: 1; }
}

@keyframes dbf-fraud-in { from { opacity: 0; transform: translateY(6px); } }
@keyframes dbf-fraud-swap { from { opacity: 0; transform: translateY(8px); filter: blur(3px); } }
@keyframes dbf-fraud-growx { from { transform: scaleX(0); } }
@keyframes dbf-fraud-draw { to { stroke-dashoffset: 0; } }
@keyframes dbf-fraud-ping { 0% { opacity: .9; transform: scale(1); } 80%, 100% { opacity: 0; transform: scale(2.6); } }
@keyframes dbf-fraud-blink { 50% { opacity: .45; } }
@keyframes dbf-fraud-bump { 40% { transform: scale(1.3); } }

/* ---------------------------------------------------------------- responsive */
@container dbf-fraud (width < 1040px) {
  .dbf-fraud__shell { grid-template-columns: 60px minmax(0, 1fr); }
  .dbf-fraud__side { padding: 18px 8px; align-items: center; }
  .dbf-fraud__lbl { display: none; }
  .dbf-fraud__brand { padding: 0 0 16px; }
  .dbf-fraud__item { padding: 10px; position: relative; & em { position: absolute; top: 2px; right: 0; padding: 0 4px; font-size: 9.5px; } }
  .dbf-fraud__qv { grid-template-columns: 260px minmax(0, 1fr); }
  .dbf-fraud__rules li { grid-template-columns: 34px minmax(0, 1fr) minmax(0, .8fr) 64px; & .v.h { display: none; } }
}
@container dbf-fraud (width < 860px) {
  .dbf-fraud__case > .body { grid-template-columns: minmax(0, 1fr); grid-template-areas: "score" "sig" "time" "geo"; }
  .dbf-fraud__acts .note { display: none; }
}
@container dbf-fraud (width < 760px) {
  .dbf-fraud__shell { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
  .dbf-fraud__side { flex-direction: row; padding: 8px 12px; border-right: 0; border-bottom: 1px solid var(--dbf-fraud-line); }
  .dbf-fraud__brand { padding: 0 8px 0 0; & svg { width: 24px; height: 24px; } }
  .dbf-fraud__nav { display: flex; gap: 2px; }
  .dbf-fraud__item { padding: 8px 12px; }
  .dbf-fraud__qv { grid-template-columns: minmax(0, 1fr); grid-template-rows: 168px minmax(0, 1fr); }
  .dbf-fraud__queue { border-right: 0; border-bottom: 1px solid var(--dbf-fraud-line); }
  .dbf-fraud__qh { grid-template-columns: auto 1fr; align-items: center; padding: 10px 12px 8px; }
  .dbf-fraud__list { display: flex; align-items: flex-start; overflow-x: auto; overflow-y: hidden; scroll-snap-type: x mandatory; gap: 6px; padding: 0 12px 12px; }
  .dbf-fraud__list li { flex: 0 0 230px; scroll-snap-align: start; box-shadow: inset 0 0 0 1px var(--dbf-fraud-line); align-content: start; }
  .dbf-fraud__case > .body { padding: 6px 12px 12px; }
  .dbf-fraud__ch { padding: 12px 12px 8px; }
  .dbf-fraud__acts { padding: 8px 12px 10px; & button { padding: 7px 10px; } }
  .dbf-fraud__dv, .dbf-fraud__rv { padding: 12px; }
  .dbf-fraud__rules li { grid-template-columns: 34px minmax(0, 1fr) 64px; & .bars { display: none; } }
}
@container dbf-fraud (width < 440px) {
  .dbf-fraud__score { grid-template-columns: 100px minmax(0, 1fr); }
  .dbf-fraud__dial { width: 100px; & b { font-size: 26px; } }
  .dbf-fraud__acts kbd { display: none; }
  .dbf-fraud__dt .h2 { display: none; }
  .dbf-fraud__ch { grid-template-columns: minmax(0, 1fr); & .big { text-align: left; } }
}

@media (prefers-reduced-motion: reduce) {
  .dbf-fraud__list li, .dbf-fraud__case.swap > *, .dbf-fraud__wf li, .dbf-fraud__wf .tr i, .dbf-fraud__dt tbody tr, .dbf-fraud__rules .bars i, .dbf-fraud__item em.bump { animation: none; }
  .dbf-fraud__tl .ring, .dbf-fraud__list .sla.late { animation: none; }
  .dbf-fraud__map .arc { animation: none; stroke-dashoffset: 0; }
  .dbf-fraud__dial, .dbf-fraud__view, .dbf-fraud__toast, .dbf-fraud__help, .dbf-fraud__hp, .dbf-fraud__sw::after { transition: none; }
}

