sevg.addEventListener('keydown', e => { const bs = $$('button', sevg), i = bs.findIndex(b => b.dataset.s === S.sev), j = e.key === 'ArrowRight' ? (i + 1) % 4 : e.key === 'ArrowLeft' ? (i + 3) % 4 : -1; if (j >= 0) { e.preventDefault(); e.stopPropagation(); setSev(bs[j].dataset.s); bs[j].focus(); } });

/* ------------------------------------------------------------------ decided + rules views */
const dt = $('.dbf-fraud__dt');
function renderDone() {
  const t = d => new Date(d).toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });
  dt.innerHTML = `<thead><tr><th>Time</th><th>Alert</th><th>Cardholder</th><th class="h2">Merchant</th><th class="r">Amount</th><th>Decision</th><th class="r h2">Handled in</th><th></th></tr></thead><tbody>${S.done.map((x, i) =>
    `<tr style="--i:${Math.min(i, 12)}"><td class="mu mono">${t(x.at)}</td><td class="mono">${x.a.id}</td><td>${esc(x.a.who)}</td><td class="mu h2">${esc(x.a.mer)}</td><td class="r mono">${usd(x.a.amt)}</td><td><span class="dz ${x.k}"><i></i>${VERB[x.k]}</span></td><td class="r mono mu h2">${mmss(x.dur)}</td><td class="r">${x.pre ? '' : `<button type="button" data-u="${i}">Undo</button>`}</td></tr>`).join('') || '<tr class="empty"><td colspan="8">Nothing decided yet.</td></tr>'}</tbody>`;
  const n = { a: 0, d: 0, e: 0 }; S.done.forEach(x => n[x.k]++);
  $('.dbf-fraud__dsum').textContent = `${n.a} approved · ${n.d} declined · ${n.e} escalated`;
}
dt.addEventListener('click', e => { const b = e.target.closest('[data-u]'); if (b) { undo(S.done[+b.dataset.u]); renderDone(); } });
const rl = $('.dbf-fraud__rules');
function renderRules() {
  const mx = Math.max(...RULES.map(r => r.hits));
  rl.innerHTML = RULES.map((r, i) => { const inQ = S.queue.filter(a => a.rules.includes(r.id)).length; return `<li class="${r.on ? '' : 'off'}"><button type="button" class="dbf-fraud__sw" role="switch" aria-checked="${r.on}" aria-label="${esc(r.n)}" data-r="${r.id}"></button><span class="nm"><b>${esc(r.n)}</b><small>${r.id} · ${esc(r.d)}</small></span>
    <span class="bars"><span title="Hits today"><i style="--w:${(r.hits / mx).toFixed(3)};--i:${i}"></i></span><span class="p" title="Confirmed fraud"><i style="--w:${(r.tp / mx).toFixed(3)};--i:${i}"></i></span></span>
    <span class="v">${Math.round(r.tp / r.hits * 100)}%<small>precision</small></span><span class="v h">${inQ}<small>in queue</small></span></li>`; }).join('');
  const sup = suppressed();
  $('.dbf-fraud__rsum').textContent = `Today: ${RULES.reduce((s, r) => s + r.hits, 0)} hits · grey bar hits, red bar confirmed fraud${sup ? ` · ${sup} alert${sup > 1 ? 's' : ''} held back` : ''}`;
}
rl.addEventListener('click', e => { const b = e.target.closest('[data-r]'); if (!b) return; const r = RULES.find(x => x.id === b.dataset.r); r.on = !r.on; renderRules(); counts(); });

/* ------------------------------------------------------------------ views, help, keyboard */
const help = $('.dbf-fraud__help');
function openHelp(on) { help.hidden = !on; if (on) $('.dbf-fraud__close', help).focus(); }
$('.dbf-fraud__help-btn').addEventListener('click', () => openHelp(true));
$('.dbf-fraud__close').addEventListener('click', () => openHelp(false));
help.addEventListener('click', e => { if (e.target === help) openHelp(false); });
function go(v) {
  S.view = v; hideTip();
  $$('.dbf-fraud__item').forEach(b => b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current'));
  $$('.dbf-fraud__view').forEach(x => x.hidden = x.dataset.view !== v);
  if (v === 'queue') { renderList(); renderCase(false); } else if (v === 'done') renderDone(); else renderRules();
}
$('.dbf-fraud__nav').addEventListener('click', e => { const b = e.target.closest('[data-view]'); if (b) go(b.dataset.view); });
root.addEventListener('keydown', e => {
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
  if (k === 'Escape' && !help.hidden) { e.preventDefault(); openHelp(false); return; }
  if (k === '?') { e.preventDefault(); openHelp(help.hidden); return; }
  if (!help.hidden) return;
  if (k === 'u') { e.preventDefault(); undo(); return; }
  if (S.view !== 'queue') return;
  if (k === 'j' || k === 'ArrowDown') { e.preventDefault(); step(1); }
  else if (k === 'k' || k === 'ArrowUp') { e.preventDefault(); step(-1); }
  else if (k === 'a' || k === 'd' || k === 'e') { e.preventDefault(); decide(k); }
});

/* ------------------------------------------------------------------ mount */
renderList(); renderCase(false);

css:
.dbf-payouts {
  /* re-theme with these four */
  --dbf-payouts-bg: oklch(0.215 0.03 215);
  --dbf-payouts-ink: oklch(0.95 0.015 200);
  --dbf-payouts-accent: oklch(0.82 0.115 62);
  --dbf-payouts-neg: oklch(0.7 0.14 22);
  /* derived: one hue per rail */
  --dbf-payouts-card: var(--dbf-payouts-accent);
  --dbf-payouts-ach: oklch(from var(--dbf-payouts-accent) calc(l - 0.02) calc(c * 0.7) 235);
  --dbf-payouts-wal: oklch(from var(--dbf-payouts-accent) calc(l - 0.03) calc(c * 0.8) 160);
  --dbf-payouts-panel: color-mix(in oklch, var(--dbf-payouts-bg), var(--dbf-payouts-ink) 5%);
  --dbf-payouts-raise: color-mix(in oklch, var(--dbf-payouts-bg), var(--dbf-payouts-ink) 10%);
  --dbf-payouts-line: color-mix(in oklch, var(--dbf-payouts-ink) 11%, transparent);
  --dbf-payouts-soft: color-mix(in oklch, var(--dbf-payouts-ink) 6%, transparent);
  --dbf-payouts-mute: color-mix(in oklch, var(--dbf-payouts-ink) 64%, var(--dbf-payouts-bg));
  --dbf-payouts-faint: color-mix(in oklch, var(--dbf-payouts-ink) 42%, var(--dbf-payouts-bg));
  --dbf-payouts-sans: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  --dbf-payouts-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --dbf-payouts-out: cubic-bezier(.16, 1, .3, 1);
  --dbf-payouts-spring: linear(0, 0.04 1.2%, 0.17 2.9%, 0.62 7.5%, 0.86 10.6%, 1.02 14%, 1.08 17%, 1.09 19.6%, 1.06 23.5%, 1.01 30%, 0.99 37%, 1);
  width: 100%;
  height: var(--dbf-payouts-h, 680px);
  container-type: inline-size; container-name: dbf-payouts;
  position: relative; isolation: isolate; overflow: hidden;
  border-radius: 18px;
  background: var(--dbf-payouts-bg);
  color: var(--dbf-payouts-ink);
  font: 13px/1.45 var(--dbf-payouts-sans);
  accent-color: var(--dbf-payouts-accent);
  color-scheme: dark;
  box-shadow: inset 0 0 0 1px var(--dbf-payouts-line);
  & *, & *::before, & *::after { box-sizing: border-box; }
  & :where(h2, h3, p, dl, dd, ul, table) { margin: 0; padding: 0; }
  & :where(button) { font: inherit; color: inherit; background: none; border: 0; padding: 0; cursor: pointer; }
  & :focus-visible { outline: 2px solid var(--dbf-payouts-accent); outline-offset: 2px; border-radius: 6px; }
}
.dbf-payouts__ic { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.dbf-payouts__shell { height: 100%; display: grid; grid-template-columns: 184px minmax(0, 1fr); }

/* ---------------------------------------------------------------- sidebar */
.dbf-payouts__side { display: flex; flex-direction: column; gap: 4px; padding: 20px 12px 16px; min-height: 0; border-right: 1px solid var(--dbf-payouts-line); background: color-mix(in oklch, var(--dbf-payouts-bg), black 16%); }
.dbf-payouts__brand {
  display: flex; align-items: center; gap: 10px; padding: 0 6px 22px;
  & svg { width: 30px; height: 30px; padding: 5px; border-radius: 9px; flex: none; background: var(--dbf-payouts-accent); fill: none; stroke: var(--dbf-payouts-bg); stroke-width: 1.9; stroke-linecap: round; stroke-linejoin: round; }
  & b { display: block; font-size: 15px; font-weight: 720; letter-spacing: -.02em; line-height: 1.1; }
  & small { display: block; font-size: 11px; color: var(--dbf-payouts-mute); }
}
.dbf-payouts__nav { display: grid; gap: 2px; }
.dbf-payouts__item {
  display: flex; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 9px; color: var(--dbf-payouts-mute); font-weight: 550; text-align: left; transition: background-color .2s, color .2s;
  &:hover { color: var(--dbf-payouts-ink); background: var(--dbf-payouts-soft); }
  &[aria-current="page"] { color: var(--dbf-payouts-ink); background: var(--dbf-payouts-raise); }
  &[aria-current="page"] .dbf-payouts__ic { color: var(--dbf-payouts-accent); }
}
.dbf-payouts__foot { margin-top: auto; padding: 12px 8px 0; border-top: 1px solid var(--dbf-payouts-line); font-size: 11.5px; color: var(--dbf-payouts-mute); text-wrap: pretty; & b { display: block; color: var(--dbf-payouts-ink); font-weight: 650; } }

/* ---------------------------------------------------------------- main + header */
.dbf-payouts__main { min-width: 0; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 14px 18px 16px; }
.dbf-payouts__head { display: flex; align-items: center; justify-content: space-between; gap: 10px 16px; flex-wrap: wrap; }
.dbf-payouts__mnav {
  display: flex; align-items: center; gap: 6px;
  & h2 { font-size: clamp(19px, 2.3cqi, 25px); font-weight: 720; letter-spacing: -.035em; min-width: 9.2em; text-align: center; font-variant-numeric: tabular-nums; }
}
.dbf-payouts__arrow {
  width: 30px; height: 30px; border-radius: 9px; display: grid; place-items: center; box-shadow: inset 0 0 0 1px var(--dbf-payouts-line); transition: background-color .15s;
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  &:hover:not([disabled]) { background: var(--dbf-payouts-soft); }
  &[disabled] { opacity: .3; cursor: default; }
}
.dbf-payouts__rails {
  display: flex; gap: 6px; flex-wrap: wrap;
  & button { display: inline-flex; align-items: center; gap: 7px; padding: 5px 11px 5px 9px; border-radius: 99px; font-size: 12px; font-weight: 600; color: var(--dbf-payouts-mute); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line); transition: background-color .2s, color .2s; }
  & button i { width: 9px; height: 9px; border-radius: 50%; background: var(--c); transition: scale .3s var(--dbf-payouts-spring), opacity .2s; }
  & button small { font: 500 10.5px var(--dbf-payouts-mono); color: var(--dbf-payouts-faint); }
  & button[aria-pressed="true"] { color: var(--dbf-payouts-ink); background: var(--dbf-payouts-soft); }
  & button[aria-pressed="false"] i { opacity: .25; scale: .7; }
}

/* ---------------------------------------------------------------- KPIs */
.dbf-payouts__kpis {
  display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px;
  & > div { padding: 9px 13px 10px; border-radius: 12px; background: var(--dbf-payouts-panel); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line); animation: dbf-payouts-rise .6s var(--dbf-payouts-out) both; animation-delay: calc(var(--i) * 55ms); min-width: 0; }
  & dt { font-size: 11px; color: var(--dbf-payouts-mute); font-weight: 550; }
  & dd { font: 600 clamp(16px, 1.9cqi, 20px)/1.2 var(--dbf-payouts-mono); letter-spacing: -.03em; font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & dd small { display: block; font: 500 11px var(--dbf-payouts-sans); letter-spacing: 0; color: var(--dbf-payouts-faint); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
}

/* ---------------------------------------------------------------- views */
.dbf-payouts__view {
  flex: 1; min-height: 0; display: grid; gap: 12px;
  transition: opacity .35s var(--dbf-payouts-out), translate .5s var(--dbf-payouts-out);
  @starting-style { opacity: 0; translate: 0 10px; }
  &[hidden] { display: none; }
}
.dbf-payouts__cv { grid-template-columns: minmax(0, 1fr) 292px; }

/* ---------------------------------------------------------------- calendar */
.dbf-payouts__calp { position: relative; min-width: 0; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr); gap: 4px; }
.dbf-payouts__wd { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); gap: 4px; & span { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbf-payouts-faint); padding: 0 8px; } }
.dbf-payouts__grid { display: grid; grid-template-columns: repeat(7, minmax(0, 1fr)); grid-auto-rows: minmax(0, 1fr); gap: 4px; min-height: 0; }
.dbf-payouts__cell {
  position: relative; min-width: 0; min-height: 0; border-radius: 10px; padding: 6px 8px; text-align: left; display: grid; grid-template-rows: auto 1fr auto; overflow: hidden;
  background: var(--dbf-payouts-panel); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line);
  transition: background-color .2s, box-shadow .2s, opacity .2s;
  animation: dbf-payouts-pop .5s var(--dbf-payouts-out) both; animation-delay: calc(var(--i) * 14ms);
  & .n { font: 600 12px var(--dbf-payouts-mono); color: var(--dbf-payouts-mute); display: flex; align-items: center; justify-content: space-between; gap: 4px; }
  & .n em { font: 600 9.5px var(--dbf-payouts-sans); font-style: normal; letter-spacing: .06em; text-transform: uppercase; padding: 1px 5px; border-radius: 5px; }
  & .v { align-self: end; font: 600 clamp(11px, 1.15cqi, 13px) var(--dbf-payouts-mono); font-variant-numeric: tabular-nums; letter-spacing: -.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .bar { display: flex; height: 4px; gap: 1px; margin-top: 4px; width: calc(var(--w) * 100%); border-radius: 2px; overflow: hidden; transform-origin: 0 50%; animation: dbf-payouts-growx .7s var(--dbf-payouts-out) both; animation-delay: calc(var(--i) * 14ms + 200ms); }
  & .bar span { flex: var(--f) 1 0; background: var(--c); }
  & .cap { font: 10.5px var(--dbf-payouts-mono); color: var(--dbf-payouts-faint); align-self: end; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; letter-spacing: -.02em; }
  &.out { opacity: .32; }
  &.we { background: transparent; }
  &.hol { background: repeating-linear-gradient(-45deg, transparent 0 5px, var(--dbf-payouts-soft) 5px 6px); }
  &.paid .n em { color: var(--dbf-payouts-wal); background: color-mix(in oklch, var(--dbf-payouts-wal) 16%, transparent); }
  &.today { box-shadow: inset 0 0 0 1.5px var(--dbf-payouts-accent); }
  &.today .n em { color: var(--dbf-payouts-bg); background: var(--dbf-payouts-accent); }
  &.est .v { color: var(--dbf-payouts-mute); }
  &.est .n em { color: var(--dbf-payouts-mute); background: var(--dbf-payouts-soft); }
  &.src { background: color-mix(in oklch, var(--dbf-payouts-panel), var(--dbf-payouts-accent) 10%); }
  &[aria-selected="true"] { background: var(--dbf-payouts-raise); box-shadow: inset 0 0 0 2px var(--dbf-payouts-ink); }
  &.po { cursor: pointer; }
  &.po:hover { background: var(--dbf-payouts-raise); }
  &:focus-visible { outline-offset: 1px; }
}
.dbf-payouts__arcs {
  position: absolute; inset: 0; width: 100%; height: 100%; pointer-events: none; overflow: visible; z-index: 2;
  & path { fill: none; stroke-linecap: round; opacity: .9; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dbf-payouts-draw .55s var(--dbf-payouts-out) forwards; animation-delay: calc(var(--i) * 45ms); }
  & circle { stroke: var(--dbf-payouts-bg); stroke-width: 2; animation: dbf-payouts-fade .3s both; animation-delay: calc(var(--i) * 45ms + 200ms); }
}

/* ---------------------------------------------------------------- day panel + waterfall */
.dbf-payouts__day {
  min-height: 0; overflow: auto; scrollbar-width: thin; padding: 14px 16px; border-radius: 14px; background: var(--dbf-payouts-panel); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line);
  animation: dbf-payouts-rise .7s var(--dbf-payouts-out) .2s both;
  & .k { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 11px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--dbf-payouts-faint); }
  & .k em { font-style: normal; letter-spacing: .04em; padding: 1px 7px; border-radius: 6px; background: var(--dbf-payouts-soft); color: var(--dbf-payouts-ink); }
  & .k em.paid { color: var(--dbf-payouts-wal); background: color-mix(in oklch, var(--dbf-payouts-wal) 16%, transparent); }
  & .k em.today { color: var(--dbf-payouts-bg); background: var(--dbf-payouts-accent); }
  & h3 { font-size: 15px; font-weight: 650; margin-top: 4px; }
  & .big { font: 600 28px/1.15 var(--dbf-payouts-mono); letter-spacing: -.04em; font-variant-numeric: tabular-nums; margin: 6px 0 2px; }
  & .ref { font: 11px var(--dbf-payouts-mono); color: var(--dbf-payouts-faint); }
  & .empty { color: var(--dbf-payouts-mute); text-wrap: pretty; margin-top: 8px; }
  & ul { list-style: none; padding: 0; margin: 12px 0 0; display: grid; gap: 4px; }
  & .src li { display: grid; grid-template-columns: 10px minmax(0, 1fr) auto; gap: 8px; align-items: center; font-size: 12px; padding: 3px 0; }
  & .src i { width: 8px; height: 8px; border-radius: 2px; background: var(--c); }
  & .src span { color: var(--dbf-payouts-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .src b { font: 600 12px var(--dbf-payouts-mono); font-variant-numeric: tabular-nums; }
}
.dbf-payouts__wf {
  width: 100%; height: 178px; display: block; margin-top: 12px; overflow: visible;
  & text { font: 10.5px var(--dbf-payouts-sans); fill: var(--dbf-payouts-mute); font-variant-numeric: tabular-nums; }
  & .val { font: 600 10.5px var(--dbf-payouts-mono); fill: var(--dbf-payouts-ink); }
  & .val.neg { fill: var(--dbf-payouts-neg); }
  & .gross { fill: color-mix(in oklch, var(--dbf-payouts-ink) 70%, transparent); }
  & .neg { fill: var(--dbf-payouts-neg); }
  & .pos { fill: var(--dbf-payouts-wal); }
  & .net { fill: var(--dbf-payouts-accent); }
  & .con { stroke: var(--dbf-payouts-faint); stroke-dasharray: 2 2; }
  & rect { transform-box: fill-box; transform-origin: 0 50%; animation: dbf-payouts-growx .55s var(--dbf-payouts-out) both; animation-delay: calc(var(--i) * 60ms); }
}

/* ---------------------------------------------------------------- ledger */
.dbf-payouts__lv { grid-template-rows: minmax(0, 1fr); }
.dbf-payouts__scroll { min-height: 0; overflow: auto; scrollbar-width: thin; border-radius: 14px; background: var(--dbf-payouts-panel); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line); scrollbar-color: color-mix(in oklch, var(--dbf-payouts-ink) 20%, transparent) transparent; }
.dbf-payouts__tbl {
  width: 100%; border-collapse: separate; border-spacing: 0; font-size: 12.5px;
  & th { position: sticky; top: 0; z-index: 1; background: var(--dbf-payouts-panel); text-align: left; padding: 0 12px; height: 34px; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--dbf-payouts-faint); border-bottom: 1px solid var(--dbf-payouts-line); white-space: nowrap; }
  & th button { letter-spacing: inherit; text-transform: inherit; font-weight: inherit; }
  & th[aria-sort="ascending"] button, & th[aria-sort="descending"] button { color: var(--dbf-payouts-ink); }
  & th[aria-sort="descending"] button::after { content: " ↓"; } & th[aria-sort="ascending"] button::after { content: " ↑"; }
  & .r { text-align: right; }
  & td { padding: 0 12px; height: 40px; border-bottom: 1px solid var(--dbf-payouts-soft); white-space: nowrap; font-variant-numeric: tabular-nums; }
  & td.m { font-family: var(--dbf-payouts-mono); font-size: 12px; }
  & .mu { color: var(--dbf-payouts-mute); }
  & .ng { color: var(--dbf-payouts-neg); }
  & tbody tr { cursor: pointer; transition: background-color .15s; }
  & tbody tr:hover { background: var(--dbf-payouts-soft); }
  & .st { display: inline-block; padding: 1px 7px; border-radius: 6px; font-size: 11px; font-weight: 700; background: var(--dbf-payouts-soft); color: var(--dbf-payouts-mute); }
  & .st.paid { color: var(--dbf-payouts-wal); background: color-mix(in oklch, var(--dbf-payouts-wal) 15%, transparent); }
  & .st.today { color: var(--dbf-payouts-bg); background: var(--dbf-payouts-accent); }
  & .mix { display: flex; width: 90px; height: 6px; gap: 1px; border-radius: 3px; overflow: hidden; }
  & .mix span { flex: var(--f) 1 0; background: var(--c); }
  & tfoot td { position: sticky; bottom: 0; background: var(--dbf-payouts-raise); font-weight: 700; border-top: 1px solid var(--dbf-payouts-line); }
}

/* ---------------------------------------------------------------- reserve */
.dbf-payouts__rv { grid-template-rows: minmax(0, 1fr); }
.dbf-payouts__resp { min-height: 0; display: flex; flex-direction: column; border-radius: 14px; background: var(--dbf-payouts-panel); box-shadow: inset 0 0 0 1px var(--dbf-payouts-line); padding: 14px 16px; }
.dbf-payouts__rh { display: flex; align-items: baseline; justify-content: space-between; gap: 6px 16px; flex-wrap: wrap; & h3 { font-size: 13px; font-weight: 700; } & p { font-size: 12px; color: var(--dbf-payouts-mute); } }
.dbf-payouts__rplot { position: relative; flex: 1; min-height: 0; margin-top: 8px; &:focus-visible { outline-offset: 2px; } }
.dbf-payouts__rsvg {
  position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible;
  & text { font: 10.5px var(--dbf-payouts-mono); fill: var(--dbf-payouts-faint); }
  & .gl { stroke: var(--dbf-payouts-soft); }
  & .area { fill: color-mix(in oklch, var(--dbf-payouts-accent) 16%, transparent); }
  & .ln { fill: none; stroke: var(--dbf-payouts-accent); stroke-width: 2; stroke-linejoin: round; stroke-dasharray: 1; stroke-dashoffset: 1; animation: dbf-payouts-draw 1.4s var(--dbf-payouts-out) .2s forwards; }
  & .fc { stroke-dasharray: 3 3; animation: none; opacity: .7; }
  & .hb { fill: color-mix(in oklch, var(--dbf-payouts-card) 60%, transparent); }
  & .rb { fill: var(--dbf-payouts-wal); }
  & .now { stroke: var(--dbf-payouts-ink); stroke-dasharray: 2 3; opacity: .5; }
  & .xh { stroke: var(--dbf-payouts-ink); opacity: 0; } & .xh.on { opacity: .4; }
  & .bars rect { transform-box: fill-box; transform-origin: 50% 100%; animation: dbf-payouts-growy .6s var(--dbf-payouts-out) both; animation-delay: calc(var(--i) * 8ms); }
