}

/* ---------------------------------------------------------------- tooltip */
.dbf-payouts__tip {
  position: absolute; left: 0; top: 0; z-index: 30; pointer-events: none; min-width: 180px; padding: 9px 11px; border-radius: 10px;
  background: color-mix(in oklch, var(--dbf-payouts-bg), white 13%); color: var(--dbf-payouts-ink); font-size: 12px; line-height: 1.5; font-variant-numeric: tabular-nums;
