  & span i { display: inline-block; width: 8px; height: 8px; border-radius: 2px; background: var(--c); margin-right: 6px; }
  & em { font-style: normal; font-weight: 600; color: var(--dbf-payouts-ink); font-family: var(--dbf-payouts-mono); }
