  .dbf-payouts__cell { padding: 4px 4px; border-radius: 7px; & .v { font-size: 9.5px; letter-spacing: -.04em; } & .n em { display: none; } }
  .dbf-payouts__wd span { padding: 0 2px; font-size: 9px; letter-spacing: .02em; }
  .dbf-payouts__cv { grid-template-rows: 330px auto; }
  .dbf-payouts__tbl .h2 { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .dbf-payouts__kpis > div, .dbf-payouts__cell, .dbf-payouts__cell .bar, .dbf-payouts__day, .dbf-payouts__wf rect, .dbf-payouts__rsvg .bars rect, .dbf-payouts__arcs circle { animation: none; }
