  const W = day.clientWidth - 32 || 260, L = 104, Rr = 6, rowH = 22, H = (steps.length + 1) * rowH + 4, mx = Math.max(b.gross, b.gross + b.rel), x = v => L + v / mx * (W - L - Rr - 54);
  let acc = 0, g = '', i = 0;
  steps.forEach(([lb, v, cls], r) => {
