    g += `<text x="0" y="${y + 13}">${lb}</text><rect class="${cls}" style="--i:${i++}" x="${x0.toFixed(1)}" y="${y + 3}" width="${w.toFixed(1)}" height="${rowH - 8}" rx="2"/><text class="val${v < 0 ? ' neg' : ''}" x="${(x(Math.max(a, z)) + 5).toFixed(1)}" y="${y + 13}">${v < 0 ? '−' : r ? '+' : ''}${k(Math.abs(v)).replace('−', '')}</text>`;
    if (r) g += `<line class="con" x1="${x(a)}" x2="${x(a)}" y1="${y - rowH + 15}" y2="${y + 3}"/>`;
    acc = z;
  });
  const y = steps.length * rowH + 4;
  g += `<line class="con" x1="${x(acc)}" x2="${x(acc)}" y1="${y - rowH + 15}" y2="${y + 3}"/><text x="0" y="${y + 13}" style="fill:var(--dbf-payouts-ink);font-weight:650">Net payout</text><rect class="net" style="--i:${i}" x="${L}" y="${y + 3}" width="${(x(acc) - L).toFixed(1)}" height="${rowH - 8}" rx="2"/><text class="val" x="${(x(acc) + 5).toFixed(1)}" y="${y + 13}">${k(acc)}</text>`;
  day.innerHTML = `<p class="k">Payout<em class="${b.st}">${STN[b.st]}${b.est && b.st === 'sched' ? ' · estimate' : ''}</em></p><h3>${dlw(b.d)}</h3><p class="big">${usd(b.net)}</p><p class="ref">${refOf(b)} · Ledger Bank ··6620</p>
    <svg class="dbf-payouts__wf" viewBox="0 0 ${W} ${H}" style="height:${H}px" role="img" aria-label="Gross ${usd(b.gross)} to net ${usd(b.net)}">${g}</svg>
    <ul class="src">${b.parts.slice().sort((p, q) => p.ri - q.ri || p.c - q.c).map(p => `<li style="--c:var(--dbf-payouts-${RAILS[p.ri].k})"><i></i><span>${RAILS[p.ri].n} captured ${dlw(p.c)}${p.est ? ' (forecast)' : ''}</span><b>${k(p.gross)}</b></li>`).join('')}</ul>`;
  if (anim && !RM) day.animate([{ opacity: .4, transform: 'translateY(6px)' }, { opacity: 1, transform: 'none' }], { duration: 380, easing: 'cubic-bezier(.16,1,.3,1)' });
}

/* ------------------------------------------------------------------ ledger */
const tbl = $('.dbf-payouts__tbl');
function renderLedger() {
  const { first, last } = monthDays(S.m), bs = []; for (let d = first; d <= last; d++) { const b = batch(d); if (b) bs.push(b); }
  const { k: key, dir } = S.sort; bs.sort((a, b) => (key === 'net' ? a.net - b.net : a.d - b.d) * dir);
  const sum = f => bs.reduce((a, b) => a + b[f], 0);
  const th = (kk, l, cls) => `<th class="${cls || ''}" ${kk ? `aria-sort="${S.sort.k === kk ? (S.sort.dir > 0 ? 'ascending' : 'descending') : 'none'}" data-k="${kk}"><button>${l}</button>` : `>${l}`}</th>`;
  tbl.innerHTML = `<thead><tr>${th('d', 'Date')}<th>Status</th><th class="h">Rails</th>${th('', 'Gross', 'r h2')}${th('', 'Fees', 'r')}${th('', 'Refunds', 'r h')}${th('', 'Reserve', 'r h')}${th('net', 'Net', 'r')}<th class="h h3">Reference</th></tr></thead>
    <tbody>${bs.map(b => `<tr data-d="${b.d}" tabindex="-1"><td>${dlw(b.d)}</td><td><span class="st ${b.st}">${STN[b.st]}${b.est && b.st === 'sched' ? '*' : ''}</span></td><td class="h"><span class="mix">${RAILS.map((r, ri) => { const v = b.parts.filter(p => p.ri === ri).reduce((a, p) => a + p.gross, 0); return v ? `<span style="--f:${v};--c:var(--dbf-payouts-${r.k})"></span>` : ''; }).join('')}</span></td>
      <td class="r m h2">${usd(b.gross)}</td><td class="r m ng">${usd(-b.fee)}</td><td class="r m ng h">${b.ref + b.cb ? usd(-(b.ref + b.cb)) : '–'}</td><td class="r m h ${b.rel - b.held < 0 ? 'ng' : ''}">${usd(b.rel - b.held)}</td><td class="r m"><b>${usd(b.net)}</b></td><td class="m mu h h3">${refOf(b)}</td></tr>`).join('')}</tbody>
    <tfoot><tr><td>${bs.length} payouts</td><td></td><td class="h"></td><td class="r m h2">${usd(sum('gross'))}</td><td class="r m ng">${usd(-sum('fee'))}</td><td class="r m ng h">${usd(-(sum('ref') + sum('cb')))}</td><td class="r m h">${usd(sum('rel') - sum('held'))}</td><td class="r m">${usd(sum('net'))}</td><td class="m mu h h3">* estimate</td></tr></tfoot>`;
  const f = tbl.querySelector('tbody tr'); if (f) f.tabIndex = 0;
}
tbl.addEventListener('click', e => {
  const th = e.target.closest('th[data-k]'); if (th) { const kk = th.dataset.k; S.sort = S.sort.k === kk ? { k: kk, dir: -S.sort.dir } : { k: kk, dir: kk === 'net' ? -1 : 1 }; renderLedger(); return; }
  const tr = e.target.closest('tbody tr'); if (tr) { S.sel = +tr.dataset.d; go('cal'); }
});
tbl.addEventListener('keydown', e => { const tr = e.target.closest('tbody tr'); if (!tr) return; const n = e.key === 'ArrowDown' ? tr.nextElementSibling : e.key === 'ArrowUp' ? tr.previousElementSibling : null; if (n) { e.preventDefault(); tr.tabIndex = -1; n.tabIndex = 0; n.focus(); } else if (e.key === 'Enter') tr.click(); });

/* ------------------------------------------------------------------ reserve */
const rplot = $('.dbf-payouts__rplot'), rsvg = $('.dbf-payouts__rsvg');
let RG = null;
function renderReserve() {
  const W = rplot.clientWidth, H = rplot.clientHeight; if (!W || !H) return;
  const a = idx(7, 1), z = idx(10, 30), n = z - a + 1, held = [], rel = [], bal = [];
  let run = 0; for (let d = 0; d < a; d++) { const b = batch(d); if (b) run += b.held - b.rel; }
  for (let d = a; d <= z; d++) { const b = batch(d); const h = b ? b.held : 0, r = b ? b.rel : 0; run += h - r; held.push(h); rel.push(r); bal.push(run); }
  const L = 56, Rr = 12, T = 12, B = 24, y1 = Math.round((H - T - B) * .66) + T, y2 = y1 + 18, bw = (W - L - Rr) / n, x = i => L + bw * (i + .5);
  const lo = Math.floor(Math.min(...bal) * .9 / 100000) * 100000, hi = Math.ceil(Math.max(...bal) * 1.04 / 100000) * 100000, fmx = Math.max(1, ...held, ...rel), y = v => y1 - (v - lo) / (hi - lo) * (y1 - T), zy = (y2 + H - B) / 2, fy = v => zy - v / fmx * (H - B - y2) / 2;
  let g = '';
  [0, .25, .5, .75, 1].forEach(f => { const v = lo + (hi - lo) * f; g += `<line class="gl" x1="${L}" x2="${W - Rr}" y1="${y(v)}" y2="${y(v)}"/><text x="${L - 8}" y="${y(v) + 3.5}" text-anchor="end">${k(v)}</text>`; });
  g += `<text x="${L - 8}" y="${zy + 3.5}" text-anchor="end">daily</text><line class="gl" x1="${L}" x2="${W - Rr}" y1="${zy}" y2="${zy}"/>`;
  for (let i = 0; i < n; i++) { const t = dateOf(a + i); if (t.getDate() === 1 || t.getDate() === 15) g += `<text x="${x(i)}" y="${H - 6}" text-anchor="middle">${dl(a + i)}</text>`; }
  const ti = TODAY - a, pts = bal.map((v, i) => `${x(i).toFixed(1)} ${y(v).toFixed(1)}`);
  g += `<path class="ln" pathLength="1" d="M${pts.slice(0, ti + 1).join('L')}"/><path class="ln fc" d="M${pts.slice(ti).join('L')}"/><text x="${L}" y="${y2 + 2}" style="fill:var(--dbf-payouts-mute)">held (up) and released (down) each payout day</text>`;
  g += `<line class="now" x1="${x(ti)}" x2="${x(ti)}" y1="${T}" y2="${H - B}"/><text x="${x(ti) + 5}" y="${T + 10}" style="fill:var(--dbf-payouts-ink)">today</text><g class="bars">`;
  const w = Math.max(1, bw * .7);
  held.forEach((v, i) => { if (v) g += `<rect class="hb" style="--i:${i}" x="${x(i) - w / 2}" y="${fy(v)}" width="${w}" height="${zy - fy(v)}"/>`; if (rel[i]) g += `<rect class="rb dn" style="--i:${i}" x="${x(i) - w / 2}" y="${zy}" width="${w}" height="${fy(-rel[i]) - zy}"/>`; });
  g += `</g><line class="xh" y1="${T}" y2="${H - B}"/>`;
  rsvg.setAttribute('viewBox', `0 0 ${W} ${H}`); rsvg.innerHTML = g;
  RG = { a, n, x, bw, L, held, rel, bal, i: RG ? RG.i : ti };
}
function resTip(i, cx, cy) { if (!RG) return; i = Math.max(0, Math.min(RG.n - 1, i)); RG.i = i; const xh = $('.xh', rsvg); xh.setAttribute('x1', RG.x(i)); xh.setAttribute('x2', RG.x(i)); xh.classList.add('on'); showTip(`<b>${dlw(RG.a + i)}${RG.a + i > TODAY ? ' · forecast' : ''}</b><span>Held<em>${k(RG.held[i])}</em></span><span>Released<em>${k(RG.rel[i])}</em></span><span>Balance<em>${k(RG.bal[i])}</em></span>`, cx, cy); }
rplot.addEventListener('pointermove', e => { if (!RG) return; const r = rplot.getBoundingClientRect(); resTip(Math.floor((e.clientX - r.left - RG.L) / RG.bw), e.clientX, e.clientY); });
rplot.addEventListener('pointerleave', () => { hideTip(); $('.xh', rsvg)?.classList.remove('on'); });
rplot.addEventListener('keydown', e => { if (!RG || (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight')) return; e.preventDefault(); const r = rplot.getBoundingClientRect(), i = RG.i + (e.key === 'ArrowRight' ? 1 : -1); resTip(i, r.left + RG.x(Math.max(0, Math.min(RG.n - 1, i))), r.top + 40); });
rplot.addEventListener('blur', hideTip);

/* ------------------------------------------------------------------ views */
function render() {
  $('.dbf-payouts__mnav h2').textContent = `${MON[S.m]} 2026`;
  $$('.dbf-payouts__arrow').forEach(b => b.disabled = S.m + +b.dataset.m < 8 || S.m + +b.dataset.m > 10);
  renderKpis(); hideTip();
  if (S.view === 'cal') renderCal(); else if (S.view === 'led') renderLedger(); else renderReserve();
}
function go(v) {
  S.view = v;
  $$('.dbf-payouts__item').forEach(b => b.dataset.view === v ? b.setAttribute('aria-current', 'page') : b.removeAttribute('aria-current'));
  $$('.dbf-payouts__view').forEach(x => x.hidden = x.dataset.view !== v);
  render();
}
$('.dbf-payouts__nav').addEventListener('click', e => { const b = e.target.closest('[data-view]'); if (b) go(b.dataset.view); });
$('.dbf-payouts__nav').addEventListener('keydown', e => {
  const bs = $$('.dbf-payouts__item'), i = bs.indexOf(document.activeElement); if (i < 0) return;
  const j = ['ArrowDown', 'ArrowRight'].includes(e.key) ? (i + 1) % bs.length : ['ArrowUp', 'ArrowLeft'].includes(e.key) ? (i - 1 + bs.length) % bs.length : -1;
  if (j >= 0) { e.preventDefault(); bs[j].focus(); }
});

/* ------------------------------------------------------------------ mount */
render();
let sz = '';
const ro = new ResizeObserver(() => {
  if (!root.isConnected) { ro.disconnect(); return; }
  const key = day.clientWidth + 'x' + rplot.clientWidth + 'x' + rplot.clientHeight;
  if (key === sz) return; sz = key;
  if (S.view === 'cal') renderDay(); else if (S.view === 'res') renderReserve();
});
ro.observe(day); ro.observe(rplot);
